local config = {
  str_homestory_N26dianying_90060101_1_dialog_content = "Bueno, estamos aquí. Lo que sea que estés buscando debería estar en este salón de clases. ¿sí?",
  str_homestory_N26dianying_90060101_2_dialog_content = "Ahhh que gran ayuda.",
  str_homestory_N26dianying_90060101_3_dialog_content = "No es frecuente ver a niños tan ansiosos en estos días.",
  str_homestory_N26dianying_90060101_4_dialog_content = "¿Qué pasa con la adulación? No lo malinterpretes, no es que realmente quiera estar aquí, es porque te escuché decir que todos podrían estar en peligro...",
  str_homestory_N26dianying_90060101_5_dialog_content = "¿Todo el mundo? Suena grandioso, mi pomposo amigo, pero tengo una idea que no es del todo precisa.",
  str_homestory_N26dianying_90060101_6_dialog_content = "Sospecho que estás mayormente preocupado por esa chica.",
  str_homestory_N26dianying_90060101_7_dialog_content = "...",
  str_homestory_N26dianying_90060101_8_dialog_content = "El presidente del consejo estudiantil, ¿hmm?",
  str_homestory_N26dianying_90060101_9_dialog_content = "¡¿C-Cómo lo supiste?!",
  str_homestory_N26dianying_90060101_10_dialog_content = "No subestimes la inteligencia del departamento de seguridad.",
  str_homestory_N26dianying_90060101_11_dialog_content = "Si no me equivoco, hay una carta de amor no enviada en tu bolsillo.",
  str_homestory_N26dianying_90060101_12_dialog_content = "!!!",
  str_homestory_N26dianying_90060101_13_dialog_content = "Ahora, ahora, simplemente no nos subestimes.",
  str_homestory_N26dianying_90060101_14_dialog_content = "Muy bien, joven, actúa con naturalidad ahora, o dejarás que el gato salga de la bolsa.",
  str_homestory_N26dianying_90060101_15_dialog_content = "Nadie lo creería de todos modos, incluso el presidente del consejo estudiantil que tanto te gusta.",
  str_homestory_N26dianying_90060101_16_dialog_content = "Bien entonces. Supongo que es mejor ir contigo.",
  str_homestory_N26dianying_90060101_17_dialog_content = "Recuerda que dijiste que la protegerías.",
  str_homestory_N26dianying_90060101_18_dialog_content = "Por supuesto. Y siempre cumplimos nuestras promesas.",
  str_homestory_N26dianying_90060101_19_dialog_content = "Mientras ella no sea la que buscamos, eso es.",
  str_homestory_N26dianying_90060101_20_dialog_content = "Vamos.",
  str_homestory_N26dianying_90060101_21_dialog_content = "Oye, ¿qué haces aquí, Kaseem?",
  str_homestory_N26dianying_90060101_22_dialog_content = "¿E-presidente del consejo estudiantil...?",
  str_homestory_N26dianying_90060101_23_dialog_content = "<size=30>¿Vaya? Realmente no esperaba que ella estuviera aquí. Bueno, eso es sospechoso...</size>",
  str_homestory_N26dianying_90060101_24_dialog_content = "<size=45>¡Presidente! ¿Cómo es que estás aquí?</size>",
  str_homestory_N26dianying_90060101_25_dialog_content = "¡No debería ser una sorpresa! Estoy revisando el equipo para el festival del campus.",
  str_homestory_N26dianying_90060101_26_dialog_content = "El vicepresidente y un estudiante servicial también están ayudando con los cheques.",
  str_homestory_N26dianying_90060101_27_dialog_content = "<size=30>Considero que existe una gran posibilidad de que se hayan escondido artículos peligrosos entre el equipo.</size>",
  str_homestory_N26dianying_90060101_28_dialog_content = "<size=30>¿Entonces, en qué estás pensando?</size>",
  str_homestory_N26dianying_90060101_29_dialog_content = "Hmm... No reconozco a tu amiga aquí, ¿ella es de nuestra escuela?",
  str_homestory_N26dianying_90060101_30_dialog_content = "Su amigo aquí... no parece ser parte de nuestra escuela.",
  str_homestory_N26dianying_90060101_31_dialog_content = "Vicepresidente...",
  str_homestory_N26dianying_90060101_32_dialog_content = "<size=30>Uh oh... ¿Es ella esa vicepresidenta demasiado cautelosa?</size>",
  str_homestory_N26dianying_90060101_33_dialog_content = "<size=30>Esto podría no ser tan fácil, a pesar de la apariencia cordial.</size>",
  str_homestory_N26dianying_90060101_34_dialog_content = "<size=30>Ayúdame a pensar en algo, rápido.</size>",
  str_homestory_N26dianying_90060101_35_dialog_content = "Lo intentaré.",
  str_homestory_N26dianying_90060101_36_dialog_content = "ella... ella es...",
  str_homestory_N26dianying_90060101_37_option_content = "Novia",
  str_homestory_N26dianying_90060101_38_dialog_content = "¡Es tu novia! ¡Haz crecer un par y solo dilo!",
  str_homestory_N26dianying_90060101_39_dialog_content = "¡E-Ella es mi novia!",
  str_homestory_N26dianying_90060101_40_dialog_content = "Er, no crees que es una elección bastante peligrosa, gordito.",
  str_homestory_N26dianying_90060101_41_dialog_content = "G-novia?!",
  str_homestory_N26dianying_90060101_42_dialog_content = "¡¿Desde cuando?!",
  str_homestory_N26dianying_90060101_43_dialog_content = "<size=30>No esperaba que estuvieras interesado en mí, joven...</size>",
  str_homestory_N26dianying_90060101_44_dialog_content = "<size=30>¡No esperaba que estuvieras interesado en mí, jovencito! Pero lo siento, mi corazón ya es de otro.</size>",
  str_homestory_N26dianying_90060101_45_dialog_content = "<size=30>¿No crees que este tipo de excusa es demasiado obvia?</size>",
  str_homestory_N26dianying_90060101_46_dialog_content = "<size=30>Y este tipo de excusa no le hace bien a la situación.</size>",
  str_homestory_N26dianying_90060101_47_dialog_content = "Lo-lo siento...",
  str_homestory_N26dianying_90060101_48_option_content = "Prima",
  str_homestory_N26dianying_90060101_49_dialog_content = "¡Solo di que es tu prima! ¡Aumentar!",
  str_homestory_N26dianying_90060101_50_dialog_content = "¡Oh, este es mi primo, sí!",
  str_homestory_N26dianying_90060101_51_dialog_content = "No se parecen en nada, apenas relacionados, gordito.",
  str_homestory_N26dianying_90060101_52_dialog_content = "¡Ay, tu prima! ¿No nos presentas?",
  str_homestory_N26dianying_90060101_53_dialog_content = "Oh, tu prima, ¿verdad? ¿No nos presentas?",
  str_homestory_N26dianying_90060101_54_dialog_content = "¿Soy solo yo, o la discrepancia de edad es un poco mala?",
  str_homestory_N26dianying_90060101_55_dialog_content = "No puedo evitar sentir que hay algo un poco extraño en la diferencia de edad.",
  str_homestory_N26dianying_90060101_56_dialog_content = "No no. Siempre se ha visto madura para su edad. Se ha visto así desde que tenía unos ocho años.",
  str_homestory_N26dianying_90060101_57_dialog_content = "¿Es eso así? Eso es realmente algo...",
  str_homestory_N26dianying_90060101_58_dialog_content = "<size=30>Estás hablando basura.</size>",
  str_homestory_N26dianying_90060101_59_dialog_content = "<size=30>Esto se siente mal... Estoy empezando a dudar del guión...</size>",
  str_homestory_N26dianying_90060101_60_dialog_content = "<size=30>¿Esto no hará que todos se centren aún más en mí?</size>",
  str_homestory_N26dianying_90060101_61_dialog_content = "<size=30>Olvídalo, esto solo hará que todos se centren aún más en mí.</size>",
  str_homestory_N26dianying_90060101_62_dialog_content = "Lo siento...",
  str_homestory_N26dianying_90060101_63_option_content = "Vecino",
  str_homestory_N26dianying_90060101_64_dialog_content = "Es mejor decir que es vecina. ¡Eso tiene que ser seguro!",
  str_homestory_N26dianying_90060101_65_dialog_content = "S-Ella es mi vecina de al lado.",
  str_homestory_N26dianying_90060101_66_dialog_content = "No puedo evitar sentir que está cavando su propia tumba, cachorrito.",
  str_homestory_N26dianying_90060101_67_dialog_content = "¿Vecino?",
  str_homestory_N26dianying_90060101_68_dialog_content = "¿El presidente del consejo estudiantil no vive junto a ti?",
  str_homestory_N26dianying_90060101_69_dialog_content = "Presidenta Theresa, ¿la reconoce?",
  str_homestory_N26dianying_90060101_70_dialog_content = "No... No, yo no...",
  str_homestory_N26dianying_90060101_71_dialog_content = "¿Te acabas de mudar a la zona?",
  str_homestory_N26dianying_90060101_72_dialog_content = "Oh, jaja... Yo, yo cometí un error.",
  str_homestory_N26dianying_90060101_73_dialog_content = "<size=30>Eres una verdadera causa perdida. ¿No se te ocurre nada mejor?</size>",
  str_homestory_N26dianying_90060101_74_dialog_content = "<size=30>¡Lo siento! Déjame pensar...</size>",
  str_homestory_N26dianying_90060101_75_dialog_content = "... ¡Entendido! Me crucé con ella de camino aquí. Es una de las ex alumnas de nuestra escuela.",
  str_homestory_N26dianying_90060101_76_dialog_content = "Había oído hablar de nuestro festival del campus, que le recordaba su tiempo aquí, así que quería venir.",
  str_homestory_N26dianying_90060101_77_dialog_content = "Entonces es así, un ex-alumno, ¿eh?",
  str_homestory_N26dianying_90060101_78_dialog_content = "Eso explica que parezca mayor.",
  str_homestory_N26dianying_90060101_79_dialog_content = "(Bien hecho, chico. Parece que lo hemos arruinado por ahora).",
  str_homestory_N26dianying_90060101_80_dialog_content = "Todo el equipo ha sido revisado, presidente.",
  str_homestory_N26dianying_90060101_81_dialog_content = "Gracias.",
  str_homestory_N26dianying_90060101_82_dialog_content = "¿D? ¿Un niño? ¿Va a cruzar el reparto del papel?",
  str_homestory_N26dianying_90060101_83_dialog_content = "Bethel está improvisando.",
  str_homestory_N26dianying_90060101_84_dialog_content = "Bueno, entonces por favor, siéntase libre de mirar alrededor y háganos saber si tiene alguna sugerencia.",
  str_homestory_N26dianying_90060101_85_dialog_content = "¡Excelente! Echaré un buen vistazo y ofreceré ideas desde la perspectiva de mi graduado.",
  str_homestory_N26dianying_90060101_86_dialog_content = "¡¿Qué es eso, señorita presidenta?!",
  str_homestory_N26dianying_90060101_87_dialog_content = "Esto es... ¿una nueva freidora ordinaria?",
  str_homestory_N26dianying_90060101_88_dialog_content = "¿Eh? Ese es el electrodoméstico que fríe la comida sin necesidad de aceite, ¿verdad?",
  str_homestory_N26dianying_90060101_89_dialog_content = "Así es. Ambos son saludables y muy populares en este momento.",
  str_homestory_N26dianying_90060101_90_dialog_content = "<size=30>Ya veo... Parece que es fácil esconder algo en esas canastas de papas fritas.</size>",
  str_homestory_N26dianying_90060101_91_dialog_content = "<size=30>Los dispositivos de interés también podrían, hipotéticamente, ser activados por el calentamiento.</size>",
  str_homestory_N26dianying_90060101_92_dialog_content = "<size=30>Los dispositivos de interés también podrían, hipotéticamente, ser activados por el calentamiento. Lo mejor es mirar dentro.</size>",
  str_homestory_N26dianying_90060101_93_dialog_content = "No se ve muy bien para cocinar, para ser honesto.",
  str_homestory_N26dianying_90060101_94_dialog_content = "Oh, esto es solo un accesorio proporcionado por nuestro club de cosplay.",
  str_homestory_N26dianying_90060101_95_dialog_content = "¿No hizo esto la... algo fábrica de alquimia?",
  str_homestory_N26dianying_90060101_96_dialog_content = "¿La fábrica de alquimia de Theresa?",
  str_homestory_N26dianying_90060101_97_dialog_content = "Muy divertido.",
  str_homestory_N26dianying_90060101_98_dialog_content = "...",
  str_homestory_N26dianying_90060101_99_dialog_content = "(¿Dices que revise el interior? ¿Crees que puedo?)",
  str_homestory_N26dianying_90060101_100_dialog_content = "¡Ese es mi plato especial!",
  str_homestory_N26dianying_90060101_101_dialog_content = "Una muy buena amiga me dio la receta. Es borscht de remolacha.",
  str_homestory_N26dianying_90060101_102_dialog_content = "Es refrescante y nutritivo para el alma.",
  str_homestory_N26dianying_90060101_103_dialog_content = "Borscht de remolacha... ¿Quieres decir...?",
  str_homestory_N26dianying_90060101_104_dialog_content = "Oh, debes haber comido el borscht de mi amigo antes, Kaseem.",
  str_homestory_N26dianying_90060101_105_dialog_content = "Yo... no sé.",
  str_homestory_N26dianying_90060101_106_dialog_content = "Esta no es una gran conversación, se mire como se mire, así que cambiemos de tema.",
  str_homestory_N26dianying_90060101_107_dialog_content = "...",
  str_homestory_N26dianying_90060101_108_dialog_content = "(¿Quieres revisar la sopa...? ¿En serio? En realidad, es bastante peligrosa).",
  str_homestory_N26dianying_90060101_108X1_dialog_content = "Hmm... Parece un poco vacío aquí.",
  str_homestory_N26dianying_90060101_108X2_dialog_content = "¿Quizás todavía están preparando las cosas?",
  str_homestory_N26dianying_90060101_108X3_dialog_content = "Es posible, pero huelo el olor del peligro cerca.",
  str_homestory_N26dianying_90060101_109_dialog_content = "¿Eh? ¿Qué dijiste?",
  str_homestory_N26dianying_90060101_110_dialog_content = "Nada. Sigue haciendo lo tuyo, solo echaré un vistazo.",
  str_homestory_N26dianying_90060101_111_dialog_content = "Ah, okey.",
  str_homestory_N26dianying_90060101_112_dialog_content = "Por cierto, Kaseem, ¿cómo van los otros preparativos para el festival?",
  str_homestory_N26dianying_90060101_113_dialog_content = "Ah, bueno, el campo de deportes...",
  str_homestory_N26dianying_90060101_114_dialog_content = "¡Oye! Estás siendo demasiado obvio. ¡Todos pueden verte escabulléndote así!",
  str_homestory_N26dianying_90060101_115_dialog_content = "...",
  str_homestory_N26dianying_90060101_116_dialog_content = "(¿Qué? ¿Quieres que encuentre una manera de ganarnos más tiempo? ¿Qué, como tener algún tipo de detector escondido en la máscara para detectar artículos peligrosos?)",
  str_homestory_N26dianying_90060101_117_dialog_content = "(¿Qué? ¿Quieres que encuentre una manera de ganarnos más tiempo? ¿Qué, como tener algún tipo de detector escondido en el bolsillo para buscar artículos peligrosos?)",
  str_homestory_N26dianying_90060101_118_dialog_content = "(¿Cómo puedes transmitir tanto solo con tus ojos?)",
  str_homestory_N26dianying_90060101_119_dialog_content = "(En realidad, ¡¿cómo es que puedo saber lo que quieres decir tan claramente?!)",
  str_homestory_N26dianying_90060101_120_dialog_content = "Diablos... Necesito cubrirla de alguna manera...",
  str_homestory_N26dianying_90060101_121_dialog_content = "¿Qué pasa, Kaseem? ¿Le pasa algo a tus ojos?",
  str_homestory_N26dianying_90060101_122_dialog_content = "Oh, Señorita Presidenta, yo...",
  str_homestory_N26dianying_90060101_123_option_content = "¡Vamos a cantar!",
  str_homestory_N26dianying_90060101_123_dialog_content = "¡No hay tiempo! ¡Usa tu voz para atraer su atención!",
  str_homestory_N26dianying_90060101_124_dialog_content = "¡Quiero cantarte la canción para el festival del campus!",
  str_homestory_N26dianying_90060101_125_dialog_content = "¿Ah?",
  str_homestory_N26dianying_90060101_126_dialog_content = "He estado practicando en secreto esta canción de la radio. Y me he esforzado mucho, ¡así que escucha!",
  str_homestory_N26dianying_90060101_127_dialog_content = "De hecho, soy un cantante increíble, ¡solo mírame tocar todas las notas altas!",
  str_homestory_N26dianying_90060101_128_dialog_content = "¿Oh? vas a cantar? ¡Entonces haré la armonía!",
  str_homestory_N26dianying_90060101_129_dialog_content = "¿Oh? vas a cantar? Déjame acompañarte con estas campanas.",
  str_homestory_N26dianying_90060101_130_dialog_content = "Repentinamente estallando en una canción como un imbécil.",
  str_homestory_N26dianying_90060101_131_dialog_content = "Qué imbécil... De repente estalló en una canción.",
  str_homestory_N26dianying_90060101_132_dialog_content = "¡Aún tenemos mucho que preparar!",
  str_homestory_N26dianying_90060101_133_dialog_content = "Todavía tenemos mucho que preparar.",
  str_homestory_N26dianying_90060101_134_option_content = "¡Por favor devuelva la cinta de video!",
  str_homestory_N26dianying_90060101_134_dialog_content = "¡Recordaste el video de repente!",
  str_homestory_N26dianying_90060101_135_dialog_content = "¡Presidente!",
  str_homestory_N26dianying_90060101_136_dialog_content = "¿Mmm?",
  str_homestory_N26dianying_90060101_137_dialog_content = "¿Puedes devolver el video que te presté?",
  str_homestory_N26dianying_90060101_138_dialog_content = "¿Eh? ¡Me lo prestaste ayer!",
  str_homestory_N26dianying_90060101_139_dialog_content = "Y accediste a prestarme \"Cloud Island Ultra Warrior: The General\" durante una semana...",
  str_homestory_N26dianying_90060101_140_dialog_content = "¿Y ahora de repente lo necesitas de vuelta?",
  str_homestory_N26dianying_90060101_141_dialog_content = "En realidad... Olvidé que había otro video en el caso... ¡Algo que no deben ver las chicas!",
  str_homestory_N26dianying_90060101_142_dialog_content = "¡El contenido de \"Railway Warrior Bros\" es demasiado sangriento!",
  str_homestory_N26dianying_90060101_143_dialog_content = "Oh, y-ya veo...",
  str_homestory_N26dianying_90060101_144_dialog_content = "Escucha, traeré el correcto un poco más tarde.",
  str_homestory_N26dianying_90060101_145_option_content = "¡Gofre!",
  str_homestory_N26dianying_90060101_145_dialog_content = "¡Ahí está! Esta película es para personas de todas las edades. ¡Mira la escala!",
  str_homestory_N26dianying_90060101_146_dialog_content = "¡Presidenta Teresa!",
  str_homestory_N26dianying_90060101_147_dialog_content = "¿Mmm?",
  str_homestory_N26dianying_90060101_148_dialog_content = "Cuál es tu tipo...?",
  str_homestory_N26dianying_90060101_149_dialog_content = "¿P-Por qué de repente me preguntas eso?",
  str_homestory_N26dianying_90060101_150_dialog_content = "S-Si insistes... Tú...",
  str_homestory_N26dianying_90060101_151_dialog_content = "¡Tonto! ¡¿Por qué hablaría de ese tipo de cosas frente a tanta gente?!",
  str_homestory_N26dianying_90060101_152_dialog_content = "Ejem... Eso está un poco fuera de lugar, Kaseem.",
  str_homestory_N26dianying_90060101_153_dialog_content = "Uh... ¿Necesitas que te disculpe?",
  str_homestory_N26dianying_90060101_154_dialog_content = "¿Es esto lo que el libro llama un impulso de línea?",
  str_homestory_N26dianying_90060101_155_dialog_content = "No hay necesidad!",
  str_homestory_N26dianying_90060101_155X1_dialog_content = "¿¡De qué estás hablando, Kaseem!?",
  str_homestory_N26dianying_90060101_156_dialog_content = "¡Bien realmente! ¿Qué piensas, mayor, soy solo yo, o Kaseem está actuando realmente extraño hoy?",
  str_homestory_N26dianying_90060101_157_dialog_content = "¿Eh? ¿Sénior? ¿Qué estás buscando allí?",
  str_homestory_N26dianying_90060101_158_dialog_content = "Vaya, parece que me han retumbar.",
  str_homestory_N26dianying_90060101_159_dialog_content = "Nada más que empezar mi investigación de nuevo... ¡Con este bolígrafo que borra recuerdos!",
  str_homestory_N26dianying_90060101_160_dialog_content = "¡Nada más que empezar de nuevo, con esta llave inglesa que borra los recuerdos...!",
  str_homestory_N26dianying_90060101_161_dialog_content = "¿Es esto una máquina expendedora, señorita presidenta?",
  str_homestory_N26dianying_90060101_162_dialog_content = "Oh, sí.",
  str_homestory_N26dianying_90060101_163_dialog_content = "Pensé que la gente podría querer una bebida para acompañar sus refrigerios.",
  str_homestory_N26dianying_90060101_164_dialog_content = "Así que encontré una manera de pedir prestado uno especialmente.",
  str_homestory_N26dianying_90060101_165_dialog_content = "Wow, eso es bastante impresionante. No me extraña que seas el presidente.",
  str_homestory_N26dianying_90060101_166_dialog_content = "¡Yo soy el que lo arrastró todo el camino hasta aquí!",
  str_homestory_N26dianying_90060101_167_dialog_content = "...",
  str_homestory_N26dianying_90060101_168_dialog_content = "(Señales oculares de nuevo... ¿Eh? ¿Se ha revisado esa área? ¿No hay artículos peligrosos?)",
  str_homestory_N26dianying_90060101_169_dialog_content = "(Sigue estancado... Esa máquina expendedora es súper sospechosa, ¡está repleta de un montón de bebidas que nunca antes había visto!)",
  str_homestory_N26dianying_90060101_170_dialog_content = "(¿Leche con sabor a menta de pescado? ¿Polvo de óxido? ¿Jugo de vegetales?)",
  str_homestory_N26dianying_90060101_171_dialog_content = "(¿Es ahora realmente el momento de preguntarse sobre eso? ¡Estoy un poco al final de mi cuerda aquí!)",
  str_homestory_N26dianying_90060101_172_dialog_content = "(¿Y de qué verdura exactamente está hecho el jugo? No es como un té extraño, ¿verdad?)",
  str_homestory_N26dianying_90060101_173_dialog_content = "Solo tengo que seguir...",
  str_homestory_N26dianying_90060101_174_dialog_content = "¿Es esto una batería, señorita presidenta?",
  str_homestory_N26dianying_90060101_175_dialog_content = "Sí, seguro que lo es.",
  str_homestory_N26dianying_90060101_176_dialog_content = "Algunos departamentos van a dar un concierto para el festival, así que lo dejaron aquí por ahora.",
  str_homestory_N26dianying_90060101_177_dialog_content = "Comprendo.",
  str_homestory_N26dianying_90060101_178_dialog_content = "...",
  str_homestory_N26dianying_90060101_179_dialog_content = "(El tipo de cosas que estamos buscando podrían estar ocultas dentro de los tambores. ¿Deberíamos abrirlos?)",
  str_homestory_N26dianying_90060101_180_dialog_content = "(Espera un momento. ¡Si están rotos, serán inútiles!)",
  str_homestory_N26dianying_90060101_182_dialog_content = "¿Un pavo, señorita presidenta?",
  str_homestory_N26dianying_90060101_183_dialog_content = "¿Por qué el festival necesita pavo?",
  str_homestory_N26dianying_90060101_184_dialog_content = "Oh, ese es el gato de un estudiante... Pero no tengo idea de dónde sacó el pavo...",
  str_homestory_N26dianying_90060101_185_dialog_content = "Correcto. Sabes, una vez tuve un gato que me ayudó a trabajar.",
  str_homestory_N26dianying_90060101_186_dialog_content = "...",
  str_homestory_N26dianying_90060101_187_dialog_content = "(¿Qué? ¿Algo podría estar escondido dentro del pavo? ¿Quieres investigar sin arruinarlo?)",
  str_homestory_N26dianying_90060101_188_dialog_content = "(¿Es eso... incluso posible? Si lo logras, tienes que enseñarme cómo).",
  str_homestory_N26dianying_90060101_188X1_dialog_content = "Esta vacio...",
  str_homestory_N26dianying_90060101_188X2_dialog_content = "¿Es esto realmente para prepararse para un festival universitario?",
  str_homestory_N26dianying_90060101_188X3_dialog_content = "Realmente es inusual. Aquí había algo antes.",
  str_homestory_N26dianying_90060101_188X4_dialog_content = "Esto es muy sospechoso. ¡Tengo que investigarlo con cuidado!",
  str_homestory_N26dianying_90060101_188X5_dialog_content = "¡Cúbreme!",
  str_homestory_N26dianying_90060101_188X6_dialog_content = "¿Eh? ¡Pero no hay cobertura aquí en absoluto!",
  str_homestory_N26dianying_90060101_190_option_content = "¡Bailar!",
  str_homestory_N26dianying_90060101_190_dialog_content = "¡Rápido, usa el movimiento que has estado practicando durante mucho tiempo!",
  str_homestory_N26dianying_90060101_191_dialog_content = "¡Olvídalo!",
  str_homestory_N26dianying_90060101_192_dialog_content = "¡Todos, por favor miren—!",
  str_homestory_N26dianying_90060101_193_dialog_content = "¡Mi asombroso, maravilloso baile!",
  str_homestory_N26dianying_90060101_193X1_dialog_content = "¿Es este movimiento el legendario baile de caminata del planeta? ¡Cachero!",
  str_homestory_N26dianying_90060101_194_dialog_content = "Aaah...!!",
  str_homestory_N26dianying_90060101_195_dialog_content = "Kaseem, hoy estás realmente...",
  str_homestory_N26dianying_90060101_196_dialog_content = "¡Excitable!",
  str_homestory_N26dianying_90060101_197_dialog_content = "¿Vaya? ¡Gracias!",
  str_homestory_N26dianying_90060101_198_dialog_content = "(¿De verdad le gusto así?)",
  str_homestory_N26dianying_90060101_199_dialog_content = "Que tonto...",
  str_homestory_N26dianying_90060101_200_dialog_content = "Has perdido la cabeza...",
  str_homestory_N26dianying_90060101_201_dialog_content = "Hoy te pasa algo muy raro.",
  str_homestory_N26dianying_90060101_202_dialog_content = "¡Impresionante! ¿Puedes enseñarme a bailar, por favor?",
  str_homestory_N26dianying_90060101_203_option_content = "¿Lectura de palma?",
  str_homestory_N26dianying_90060101_203_dialog_content = "¡Rápidamente, usa el conocimiento que aprendiste de los libros...!",
  str_homestory_N26dianying_90060101_203X1_dialog_content = "¡Sí! Recuerda ahora los puntos mencionados en el libro \"Acércate a tus enemigos rápidamente\"...",
  str_homestory_N26dianying_90060101_203X2_dialog_content = "¡Es obvio por el título del libro que hay muchos problemas con él, chubb!",
  str_homestory_N26dianying_90060101_204_dialog_content = "¡Permítanme leer sus fortunas en sus palmas!",
  str_homestory_N26dianying_90060101_205_dialog_content = "Lo siento... No puedo aceptar eso, ni siquiera como relleno de conversación.",
  str_homestory_N26dianying_90060101_206_dialog_content = "¿Eres un idiota? ¡Mejor déjame leer tu palma!",
  str_homestory_N26dianying_90060101_207_dialog_content = "Mientras estamos en eso, déjame asegurarme de que tu línea de vida termine hoy.",
  str_homestory_N26dianying_90060101_208_dialog_content = "Claro, y solo confirmaré que tu línea de vida termina hoy.",
  str_homestory_N26dianying_90060101_209_dialog_content = "¡Bien realmente! ¿Qué piensas, mayor, soy solo yo, o Kaseem está actuando realmente extraño hoy?",
  str_homestory_N26dianying_90060101_210_dialog_content = "¿Eh? ¿Sénior? ¿Qué estás buscando por ahí?",
  str_homestory_N26dianying_90060101_211_dialog_content = "Vaya, parece que me han retumbar.",
  str_homestory_N26dianying_90060101_212_dialog_content = "¡Nada más que empezar de nuevo, con esta pluma que borra recuerdos...!",
  str_homestory_N26dianying_90060101_213_dialog_content = "¡Nada más que empezar de nuevo, con esta llave inglesa que borra los recuerdos...!",
  str_homestory_N26dianying_90060101_214_option_content = "¿OVNI?",
  str_homestory_N26dianying_90060101_214_dialog_content = "¡Los métodos extremadamente tradicionales suelen ser los más efectivos!",
  str_homestory_N26dianying_90060101_215_dialog_content = "¡Por ahí! ¡UN OVNI!",
  str_homestory_N26dianying_90060101_216_dialog_content = "¡Vistazo rápido!",
  str_homestory_N26dianying_90060101_217_dialog_content = "¡OVNI! ¡Por ahí!",
  str_homestory_N26dianying_90060101_218_dialog_content = "...",
  str_homestory_N26dianying_90060101_219_dialog_content = "...",
  str_homestory_N26dianying_90060101_220_dialog_content = "...",
  str_homestory_N26dianying_90060101_220X1_dialog_content = "...",
  str_homestory_N26dianying_90060101_221_dialog_content = "Bien realmente. ¿Lo mirarías, mayor? Kaseem está actuando realmente extraño hoy.",
  str_homestory_N26dianying_90060101_222_dialog_content = "¿Eh? ¿Sénior? ¿Qué estás buscando allí?",
  str_homestory_N26dianying_90060101_223_dialog_content = "Vaya, parece que me han retumbar.",
  str_homestory_N26dianying_90060101_224_dialog_content = "¡Nada más que empezar de nuevo, con esta pluma que borra recuerdos...!",
  str_homestory_N26dianying_90060101_225_dialog_content = "¡Nada más que empezar de nuevo, con esta llave inglesa que borra los recuerdos...!",
  str_homestory_N26dianying_90060101_226_dialog_content = "...",
  str_homestory_N26dianying_90060101_227_dialog_content = "(Terminé de revisar aquí, ¿y todavía nada?)",
  str_homestory_N26dianying_90060101_228_dialog_content = "¿Qué es esto, señorita presidenta?",
  str_homestory_N26dianying_90060101_229_dialog_content = "¡Vaya! Olvidé decir.",
  str_homestory_N26dianying_90060101_230_dialog_content = "¡Este es el punto culminante del festival!",
  str_homestory_N26dianying_90060101_231_dialog_content = "Simplemente tira aquí y la máquina pone un huevo.",
  str_homestory_N26dianying_90060101_232_dialog_content = "Hay un montón de platos diferentes y sabrosos dentro de cada huevo. ¡Es un artilugio maravilloso!",
  str_homestory_N26dianying_90060101_233_dialog_content = "¿Cuándo conseguimos una máquina tan asombrosa...?",
  str_homestory_N26dianying_90060101_234_dialog_content = "Nuestro muy amable estudiante lo donó. Aparentemente, es bastante caro.",
  str_homestory_N26dianying_90060101_235_dialog_content = "Las cosas buenas hay que compartirlas con todos, jejeje.",
  str_homestory_N26dianying_90060101_236_dialog_content = "Las cosas favoritas de todos están adentro, jejeje.",
  str_homestory_N26dianying_90060101_237_dialog_content = "Tal vez deberíamos aprovechar la oportunidad para probarlo nuevamente y darle a Kaseem y a nuestro superior la oportunidad de ver lo increíble que es.",
  str_homestory_N26dianying_90060101_238_dialog_content = "<size=30>Este artilugio es sospechoso y el último lugar donde se podría ocultar algo peligroso. Deberíamos aprovechar esta oportunidad.</size>",
  str_homestory_N26dianying_90060101_239_dialog_content = "<size=30>Entendido. No te preocupes.</size>",
  str_homestory_N26dianying_90060101_240_dialog_content = "Entonces, por favor...",
  str_homestory_N26dianying_90060101_243_dialog_content = "<size=30>¿Cómo es posible... Recibimos mala inteligencia?</size>",
  str_homestory_N26dianying_90060101_244_dialog_content = "<size=30>¿Asi que que hacemos?</size>",
  str_homestory_N26dianying_90060101_245_dialog_content = "<size=30>Salgamos de aquí por ahora. Podría ser retumbar si nos quedamos mucho más tiempo.</size>",
  str_homestory_N26dianying_90060101_246_dialog_content = "Ah, todavía tengo cosas que hacer. Me temo que necesito irme.",
  str_homestory_N26dianying_90060101_247_dialog_content = "Te deseo todo lo mejor para tu festival universitario.",
  str_homestory_N26dianying_90060101_248_dialog_content = "Ah bien. Gracias, mayor.",
  str_homestory_N26dianying_90060101_249_dialog_content = "¿Salir, así como así? Hay algo sospechoso en este mayor.",
  str_homestory_N26dianying_90060101_250_dialog_content = "...",
  str_homestory_N26dianying_90060101_251_option_content = "El presidente lo opera",
  str_homestory_N26dianying_90060101_252_dialog_content = "¡Deja que la protagonista lo haga!",
  str_homestory_N26dianying_90060101_253_dialog_content = "¿Al presidente le gustaría operarlo?",
  str_homestory_N26dianying_90060101_254_dialog_content = "¿Realmente quiere que el presidente lo haga? ¿No has olvidado algo importante, gordito?",
  str_homestory_N26dianying_90060101_255_dialog_content = "Bien entonces, haré el ridículo.",
  str_homestory_N26dianying_90060101_256_dialog_content = "¡Hrrrnnnng—!",
  str_homestory_N26dianying_90060101_257_dialog_content = "¡Decir ah! Realmente no pensé que habría un huevo.",
  str_homestory_N26dianying_90060101_258_dialog_content = "parece un huevo normal...",
  str_homestory_N26dianying_90060101_259_dialog_content = "Hay tiramisú adentro.",
  str_homestory_N26dianying_90060101_260_dialog_content = "¿Podría haberse equivocado la inteligencia? Nada más que seguir buscando.",
  str_homestory_N26dianying_90060101_261_option_content = "Operalo tu mismo",
  str_homestory_N26dianying_90060101_262_dialog_content = "Dejame hacerlo. Al menos estarás tranquilo.",
  str_homestory_N26dianying_90060101_263_dialog_content = "¡Lo haré!",
  str_homestory_N26dianying_90060101_264_dialog_content = "Sólo tire aquí, ¿verdad?",
  str_homestory_N26dianying_90060101_265_dialog_content = "Sip.",
  str_homestory_N26dianying_90060101_266_dialog_content = "¡Hecho!",
  str_homestory_N26dianying_90060101_267_dialog_content = "Está parpadeando, ¿y parece que hay un milhojas dentro?",
  str_homestory_N26dianying_90060101_268_dialog_content = "<color=#e8d9bb>bip—bip—</color>",
  str_homestory_N26dianying_90060101_269_dialog_content = "¡Esperar! ¡¿Qué es esto?!",
  str_homestory_N26dianying_90060101_270_dialog_content = "¡Maldita sea, descubierto! ¡Entonces los tendré a todos—!",
  str_homestory_N26dianying_90060101_271_dialog_content = "¡¿Qué está pasando?!",
  str_homestory_N26dianying_90060101_272_dialog_content = "¿Que esta pasando? ¡He estado esperando toda la noche el clímax, gordito!",
  str_homestory_N26dianying_90060101_273_option_content = "invitar al mayor",
  str_homestory_N26dianying_90060101_274_dialog_content = "Hmm, ha traído un dispositivo para detectar objetos peligrosos, así que tal vez sea más seguro dejar que el mayor revise.",
  str_homestory_N26dianying_90060101_275_dialog_content = "¿Al mayor le gustaría intentarlo?",
  str_homestory_N26dianying_90060101_275X1_dialog_content = "Hmm, ¡te ves un poco más inteligente, gordito!",
  str_homestory_N26dianying_90060101_276_dialog_content = "Oh, sabia elección. Claro, lo intentaré.",
  str_homestory_N26dianying_90060101_277_dialog_content = "¿Este huevo tiene un sabroso manjar adentro?",
  str_homestory_N26dianying_90060101_278_dialog_content = "Creo que es un pastel de selva negra por dentro.",
  str_homestory_N26dianying_90060101_279_dialog_content = "(¿Eh? Mi detector está reaccionando).",
  str_homestory_N26dianying_90060101_280_dialog_content = "¡Nadie se mueva! Estoy con el departamento de seguridad!",
  str_homestory_N26dianying_90060101_281_dialog_content = "Aquí está mi placa. Ahora, traeré a todos para interrogarlos.",
  str_homestory_N26dianying_90060101_282_dialog_content = "¿Sénior?",
  str_homestory_N26dianying_90060101_283_dialog_content = "¡Maldita sea, descubierto! ¡Entonces los tendré a todos—!",
  str_homestory_N26dianying_90060101_284_dialog_content = "¿eh? ¿Qué estás haciendo, estudiante entusiasta desconocido?",
  str_homestory_N26dianying_90060101_285_dialog_content = "¿Eh? ¿Qué? ¿Por qué no funciona el controlador?",
  str_homestory_N26dianying_90060101_286_dialog_content = "¿Eh? ¿Qué? ¿Por qué no funciona el controlador? ¿El departamento de utilería no lo cuidó bien?",
  str_homestory_N26dianying_90060101_287_dialog_content = "Demasiado crédulo, el detector en mi máscara tiene un bloqueador de pequeño alcance.",
  str_homestory_N26dianying_90060101_288_dialog_content = "Demasiado crédulo, mi detector tiene un bloqueador de pequeño alcance.",
  str_homestory_N26dianying_90060101_289_dialog_content = "Maldita sea... Tan pronto como se active, toda la escuela se convertirá en dulces, ¡como esas casas de dulces en los cuentos de hadas!",
  str_homestory_N26dianying_90060101_290_dialog_content = "Podría escapar escondiéndome dentro de una pared de chocolate...",
  str_homestory_N26dianying_90060101_291_dialog_content = "Si es posible, me gustaría volar lejos en un barco de chocolate.",
  str_homestory_N26dianying_90060101_292_dialog_content = "... Entonces, entonces los niveles de azúcar en la sangre serán demasiado altos... ¡No! ¡Es muy peligroso!",
  str_homestory_N26dianying_90060101_293_dialog_content = "He estado observando su Imperio de Carbohidratos por un tiempo, así que será mejor que vengan en silencio.",
  str_homestory_N26dianying_90060101_294_dialog_content = "He estado observando su Sugar Kingdom por un tiempo, así que será mejor que vengan en silencio.",
  str_homestory_N26dianying_90060101_295_dialog_content = "¿Crees que me tomarás tan fácilmente?",
  str_homestory_N26dianying_90060101_296_dialog_content = "¿Eh? ¡No puedo moverme!",
  str_homestory_N26dianying_90060101_297_dialog_content = "¡Ugh...!",
  str_homestory_N26dianying_90060101_298_dialog_content = "P-Presidente...!",
  str_homestory_N26dianying_90060101_299_dialog_content = "Tú...! ¡Estudiante entusiasta!",
  str_homestory_N26dianying_90060101_300_dialog_content = "Tuviste suerte esta vez. Supongo que tendré que usar el as bajo la manga.",
  str_homestory_N26dianying_90060101_301_dialog_content = "¡Pero nuestro noble sueño de convertir a la gente en adicta al azúcar no se extinguirá!",
  str_homestory_N26dianying_90060101_302_dialog_content = "¡Ya veremos!",
  str_homestory_N26dianying_90060101_303_dialog_content = "No... no te dejaré ir...",
  str_homestory_N26dianying_90060101_304_dialog_content = "¡¿Vicepresidente?!",
  str_homestory_N26dianying_90060101_305_dialog_content = "¿Crees que puedes causar tanto alboroto en el festival del campus y luego irte tan fácilmente?",
  str_homestory_N26dianying_90060101_306_dialog_content = "¡¿Qué?! ¿Cómo es que puedes moverte?",
  str_homestory_N26dianying_90060101_307_dialog_content = "¡¿Qué?! ¿Cómo es que puedes moverte? ¡Director! ¡Esto no está bien!",
  str_homestory_N26dianying_90060101_308_dialog_content = "¿Quién interfirió con nuestro equipo? Su departamento de seguridad nunca podría lograr esto, entonces, ¿QUIÉN FUE?",
  str_homestory_N26dianying_90060101_309_dialog_content = "¡Toma esto!",
  str_homestory_N26dianying_90060101_310_dialog_content = "Entrega todos los postres!",
  str_homestory_N26dianying_90060101_311_dialog_content = "Se han llevado al tipo que quería enganchar a todo el mundo al azúcar en el festival.",
  str_homestory_N26dianying_90060101_312_dialog_content = "Oh... Y allí estaba yo, pensando que en realidad era solo un estudiante entusiasta.",
  str_homestory_N26dianying_90060101_313_dialog_content = "También he recuperado todos los postres.",
  str_homestory_N26dianying_90060101_314_dialog_content = "De todos modos, al menos la paz ha vuelto al campus.",
  str_homestory_N26dianying_90060101_315_dialog_content = "¡Por supuesto! Este es nuestro campus, después de todo.",
  str_homestory_N26dianying_90060101_316_dialog_content = "No es solo ese senior del departamento de seguridad. Mucha gente también lo está buscando.",
  str_homestory_N26dianying_90060201_1_dialog_content = "¡Dios mío, ya llego tarde! Solo espero que el contacto no se haya ido todavía...",
  str_homestory_N26dianying_90060201_2_dialog_content = "Perdóneme señor, ¿pero es este el Thorngate Inn?",
  str_homestory_N26dianying_90060201_3_dialog_content = "De hecho, es.",
  str_homestory_N26dianying_90060201_4_dialog_content = "Servimos todo tipo de comida aquí, perfecta para un viajero cansado.",
  str_homestory_N26dianying_90060201_5_dialog_content = "Sin mencionar algunas bebidas que no encontrarás en ningún otro lugar del mundo.",
  str_homestory_N26dianying_90060201_6_dialog_content = "¿Por qué no quedarse un rato y probar mis productos?",
  str_homestory_N26dianying_90060201_7_dialog_content = "Puede que mi posada no parezca gran cosa, pero nuestros platos han ganado concursos en todo el reino.",
  str_homestory_N26dianying_90060201_8_dialog_content = "¿Ver? Allí está nuestro trofeo más grande hasta ahora.",
  str_homestory_N26dianying_90060201_9_dialog_content = "Seguro que es un trofeo interesante...",
  str_homestory_N26dianying_90060201_10_dialog_content = "También tenemos varios sacos de arena repartidos por toda la posada.",
  str_homestory_N26dianying_90060201_11_dialog_content = "Si quieres, puedes estirar las piernas un rato.",
  str_homestory_N26dianying_90060201_12_dialog_content = "¿Qué hace este tipo de cosa en una posada...?",
  str_homestory_N26dianying_90060201_13_dialog_content = "Bueno, la posada se ve bastante limpia... Sí, creo que me quedaré por un tiempo.",
  str_homestory_N26dianying_90060201_14_dialog_content = "Justo ahí hay un asiento vacío. Siéntete como en casa, amigo.",
  str_homestory_N26dianying_90060201_15_dialog_content = "Este lugar funciona bastante bien por sí mismo. . .",
  str_homestory_N26dianying_90060201_16_dialog_content = "¡Ni siquiera es la hora de comer, pero la posada está llena de clientes!",
  str_homestory_N26dianying_90060201_17_dialog_content = "En cualquier caso, estoy aquí para ver a un viejo conocido, así que no necesitaré mi propia mesa.",
  str_homestory_N26dianying_90060201_18_dialog_content = "Bueno, el estilo parece fuera de lugar aquí.",
  str_homestory_N26dianying_90060201_19_dialog_content = "¿Lo compró el posadero mientras viajaba a un país extranjero?",
  str_homestory_N26dianying_90060201_20_dialog_content = "En cualquier caso, estoy aquí para ver a un viejo conocido, así que no necesitaré mi propia mesa.",
  str_homestory_N26dianying_90060201_21_dialog_content = "Ahora, eso es ir demasiado lejos...",
  str_homestory_N26dianying_90060201_22_dialog_content = "No creo que una colcha sea realmente necesaria, ¡incluso si hace un poco de frío!",
  str_homestory_N26dianying_90060201_23_dialog_content = "En cualquier caso, estoy aquí para ver a un viejo conocido, así que no necesitaré mi propia mesa.",
  str_homestory_N26dianying_90060201_23X1_dialog_content = "Es una pena que la tienda todavía esté en proceso de renovación... Ni siquiera hay mesas o sillas.",
  str_homestory_N26dianying_90060201_23X2_dialog_content = "Como eres el único invitado, puedes comer de pie justo en el mostrador.",
  str_homestory_N26dianying_90060201_23X3_dialog_content = "¿Qué? ¿¡Crees que puedo alcanzar el mostrador!?",
  str_homestory_N26dianying_90060201_23X4_dialog_content = "Yo tampoco sé qué hacer. Todo lo que puedo hacer es pedirte que trates de ser más alto.",
  str_homestory_N26dianying_90060201_23X5_dialog_content = "¿¡No crees que soy demasiado mayor para seguir creciendo!?",
  str_homestory_N26dianying_90060201_23X6_dialog_content = "Además, ¡realmente no hay nadie aquí! ¿Estoy en el lugar correcto?",
  str_homestory_N26dianying_90060201_23X7_dialog_content = "¡Maldita sea! Busca por aquí de nuevo. Tal vez haya otro Thorngate Inn.",
  str_homestory_N26dianying_90060201_23X8_dialog_content = "...",
  str_homestory_N26dianying_90060201_24_dialog_content = "Ah, claro. Haz lo que quieras, entonces.",
  str_homestory_N26dianying_90060201_25_dialog_content = "Bien, ahora repasemos la misión una vez más...",
  str_homestory_N26dianying_90060201_26_dialog_content = "\"Ve a Thorngate Inn y ponte en contacto con el misterioso guerrero\".",
  str_homestory_N26dianying_90060201_27_dialog_content = "\"El secreto es de suma importancia, por lo que el guerrero ha optado por mantener oculta su identidad\".",
  str_homestory_N26dianying_90060201_28_dialog_content = "\"Solo debes saber que el guerrero en cuestión está en el mejor momento de su vida y que sus artes marciales son insuperables\".",
  str_homestory_N26dianying_90060201_29_dialog_content = "\"Una vez en Thorngate Inn, pide una jarra de vino osmanthus y el guerrero se te acercará\".",
  str_homestory_N26dianying_90060201_30_dialog_content = "\"Después de hacer contacto, entrégales el elixir que tienes y el mundo volverá a estar en paz\".",
  str_homestory_N26dianying_90060201_31_dialog_content = "\"¡La mejor de las suertes, valiente héroe!\"",
  str_homestory_N26dianying_90060201_32_dialog_content = "¡Suficientemente simple! ¡Solo tengo que encontrar a la persona adecuada, y mi búsqueda está completa!",
  str_homestory_N26dianying_90060201_33_dialog_content = "Ahora veamos cuál de los invitados es el guerrero que busco...",
  str_homestory_N26dianying_90060201_34_dialog_content = "¡Vaya! ¡O-Por ahí!",
  str_homestory_N26dianying_90060201_35_dialog_content = "Vestido completamente de negro, con un comportamiento solemne y reservado... ¡Un maestro guerrero que intenta mantener un perfil bajo!",
  str_homestory_N26dianying_90060201_36_dialog_content = "¡Ella debe ser la persona que estoy buscando! Ahora para el siguiente paso!",
  str_homestory_N26dianying_90060201_37_dialog_content = "¡Posadero! ¡Una jarra de su mejor vino osmanthus, por favor!",
  str_homestory_N26dianying_90060201_38_dialog_content = "¡Ya viene! Voy a dejar esto aquí para usted.",
  str_homestory_N26dianying_90060201_39_dialog_content = "No mucha gente bebe esto hoy en día, pero disfrútalo.",
  str_homestory_N26dianying_90060201_40_dialog_content = "Eso está perfectamente bien. Algunas cosas deben mantenerse en \"secreto\", ¿verdad?",
  str_homestory_N26dianying_90060201_41_dialog_content = "Perdóneme, pero ¿le importaría tomar una copa conmigo?",
  str_homestory_N26dianying_90060201_42_dialog_content = "... No. Ahora vete.",
  str_homestory_N26dianying_90060201_43_dialog_content = "¡Pero es una olla de vino osmanthus! ¡Osmanto! No mucha gente lo sabe, ¿sabes?",
  str_homestory_N26dianying_90060201_44_dialog_content = "Además... ¡Pareces el tipo de persona a la que le gusta este tipo de bebida! ¿Derecho? ¿¿¿Derecho???",
  str_homestory_N26dianying_90060201_45_dialog_content = "... ¿Quién eres tú para decirme mis propias preferencias?",
  str_homestory_N26dianying_90060201_46_dialog_content = "Mejor aún... ¿Quién eres tú, de todos modos?",
  str_homestory_N26dianying_90060201_47_dialog_content = "¡Shh! Te lo diré, pero bájalo...",
  str_homestory_N26dianying_90060201_48_dialog_content = "La verdad es que sé quién eres en realidad...",
  str_homestory_N26dianying_90060201_49_dialog_content = "¡¿Tú haces?!",
  str_homestory_N26dianying_90060201_50_dialog_content = "¡E-Espera! Sólo mantén la calma, ¿de acuerdo?",
  str_homestory_N26dianying_90060201_51_dialog_content = "Si sabes quién soy... Entonces no puedo permitir que vivas.",
  str_homestory_N26dianying_90060201_52_dialog_content = "¿Qué? ¡No! ¡Quiero decir que sé que mantienes tu identidad en secreto! Es porque tu búsqueda es de suma importancia, ¿recuerdas?",
  str_homestory_N26dianying_90060201_53_dialog_content = "¡Estoy aqui para ayudarte!",
  str_homestory_N26dianying_90060201_54_dialog_content = "Ayúdame...?",
  str_homestory_N26dianying_90060201_55_dialog_content = "¿Con qué, podría preguntar?",
  str_homestory_N26dianying_90060201_56_dialog_content = "Sé que tus artes marciales son insuperables en el mundo y que estás en el mejor momento de tu vida...",
  str_homestory_N26dianying_90060201_57_dialog_content = "Pero para proteger el mundo, hay una cosa más que necesitas.",
  str_homestory_N26dianying_90060201_58_dialog_content = "... ¿De qué diablos estás hablando?",
  str_homestory_N26dianying_90060201_59_dialog_content = "¡El elixir, por supuesto! ¡Lo tengo justo aquí, solo para ti!",
  str_homestory_N26dianying_90060201_60_dialog_content = "Re... ¿En serio?!",
  str_homestory_N26dianying_90060201_61_dialog_content = "¿Podría esto realmente estar pasando...?",
  str_homestory_N26dianying_90060201_62_dialog_content = "¡Así es! Lo siento si llegué tarde.",
  str_homestory_N26dianying_90060201_63_dialog_content = "¡Esta bien! ¡Solo entrégalo ya!",
  str_homestory_N26dianying_90060201_64_dialog_content = "¡Con este veneno, finalmente puedo asesinar al gobernante de la isla y traer la paz al mundo una vez más!",
  str_homestory_N26dianying_90060201_65_dialog_content = "¡Con este veneno, finalmente puedo asesinar al señor de la ciudad y traer la paz al mundo una vez más!",
  str_homestory_N26dianying_90060201_66_dialog_content = "P-veneno?!",
  str_homestory_N26dianying_90060201_67_dialog_content = "Como ya sabes quién soy, supongo que no tiene sentido mantenerlo en secreto.",
  str_homestory_N26dianying_90060201_68_dialog_content = "Tu suposición fue correcta: soy el asesino de clase mundial que estabas buscando todo el tiempo.",
  str_homestory_N26dianying_90060201_69_dialog_content = "E-Espera... ¡¿Estuve buscando un asesino todo este tiempo?!",
  str_homestory_N26dianying_90060201_70_dialog_content = "Mis esfuerzos por asesinar al gobernante de la isla han sido infructuosos hasta ahora, pero con este veneno...",
  str_homestory_N26dianying_90060201_71_dialog_content = "Mis esfuerzos por asesinar al señor de la ciudad han sido infructuosos hasta ahora, pero con este veneno...",
  str_homestory_N26dianying_90060201_72_dialog_content = "¡Date prisa y dámelo!",
  str_homestory_N26dianying_90060201_73_dialog_content = "¡No no no! ¡Creo que esto debe ser algún tipo de malentendido!",
  str_homestory_N26dianying_90060201_74_dialog_content = "¡Este elixir no es veneno en absoluto! Además...",
  str_homestory_N26dianying_90060201_75_dialog_content = "¿No estamos en un país sin salida al mar? ¡¿De qué \"gobernante de la isla\" estás hablando?!",
  str_homestory_N26dianying_90060201_76_dialog_content = "Ahora que lo mencionas, es un poco extraño... ¡No veo el océano por aquí!",
  str_homestory_N26dianying_90060201_77_dialog_content = "¡Por supuesto no! ¡Estamos a miles de kilómetros de la playa más cercana!",
  str_homestory_N26dianying_90060201_78_dialog_content = "Los cerezos en flor también son diferentes... Incluso hay frutas que crecen en ellos.",
  str_homestory_N26dianying_90060201_79_dialog_content = "¡¿Qué \"cerezos en flor\"?! ¡Esos son árboles de durazno!",
  str_homestory_N26dianying_90060201_80_dialog_content = "¿No estamos en campo abierto? ¡¿De qué \"gobernante de la ciudad\" estás hablando?!",
  str_homestory_N26dianying_90060201_81_dialog_content = "¡¿De dónde diablos saliste?!",
  str_homestory_N26dianying_90060201_82_dialog_content = "Yo tampoco estoy seguro... Todo lo que sé es que debo llevar a cabo mi asesinato del gobernante de la isla.",
  str_homestory_N26dianying_90060201_83_dialog_content = "Yo tampoco estoy seguro... Todo lo que sé es que debo llevar a cabo mi asesinato del señor de la ciudad.",
  str_homestory_N26dianying_90060201_84_dialog_content = "¡Entonces al menos deberías tratar de estar en el lugar correcto!",
  str_homestory_N26dianying_90060201_85_dialog_content = "¿Sabes que? Finjamos que esta conversación nunca sucedió... Siento molestarte.",
  str_homestory_N26dianying_90060201_86_dialog_content = "Además, intenta ir hacia el este la próxima vez... Incluso podrías ver el océano algún día.",
  str_homestory_N26dianying_90060201_87_dialog_content = "Además, intenta ir hacia el este la próxima vez... Puede que incluso encuentres la ciudad que estás buscando.",
  str_homestory_N26dianying_90060201_88_dialog_content = "Pero espera, el veneno...",
  str_homestory_N26dianying_90060201_89_dialog_content = "¡Solo olvídalo! ¡¡Buena suerte con tu misión, y buen día!!",
  str_homestory_N26dianying_90060201_90_dialog_content = "Uf... ¿Dónde diablos está esta persona con la que se supone que debo encontrarme?",
  str_homestory_N26dianying_90060201_91_dialog_content = "Metí la pata con esa persona hace un momento... Era lo suficientemente misteriosa, pero no había nada heroico en ella en absoluto. Supongo que tendré que volver a intentarlo...",
  str_homestory_N26dianying_90060201_92_dialog_content = "Oye... ¡Esa persona me parece bastante heroica!",
  str_homestory_N26dianying_90060201_93_dialog_content = "¡Posadero! ¡Otra jarra de vino osmanthus!",
  str_homestory_N26dianying_90060201_94_dialog_content = "¡Ya viene! Voy a dejar esto aquí para usted.",
  str_homestory_N26dianying_90060201_95_dialog_content = "No hay duda... ¡Tiene que ser la persona adecuada!",
  str_homestory_N26dianying_90060201_96_dialog_content = "Perdóneme, pero ¿le importaría tomar una copa conmigo?",
  str_homestory_N26dianying_90060201_97_dialog_content = "¿Vaya? Por todos los medios.",
  str_homestory_N26dianying_90060201_98_dialog_content = "¿Vaya? Por todos los medios.",
  str_homestory_N26dianying_90060201_99_dialog_content = "¡Pedí una olla de vino osmanthus! El posadero dice que su sabor es bastante único. ¿Es esto... algo que te gustaría?",
  str_homestory_N26dianying_90060201_100_dialog_content = "En seguida.",
  str_homestory_N26dianying_90060201_101_dialog_content = "¿Gusta? ¡Me encanta!",
  str_homestory_N26dianying_90060201_102_dialog_content = "Que-?! ¡Te lo bebiste todo de un trago!",
  str_homestory_N26dianying_90060201_103_dialog_content = "Para que a alguien le guste tanto el vino osmanthus... ¡Debe ser la persona que busco!",
  str_homestory_N26dianying_90060201_104_dialog_content = "Para que a alguien le guste tanto el vino osmanthus... ¡Debe ser la persona que busco!",
  str_homestory_N26dianying_90060201_105_dialog_content = "Escucha, héroe, sé quién eres realmente. Verás, yo...",
  str_homestory_N26dianying_90060201_106_dialog_content = "¡Shhh! ¡No tan alto!",
  str_homestory_N26dianying_90060201_107_dialog_content = "¡Correcto! Casi lo olvido... \"Máximo secreto\", ¡y todo eso!",
  str_homestory_N26dianying_90060201_108_dialog_content = "Has venido a ponerte en contacto conmigo, ¿sí? He estado esperando por tanto tiempo...",
  str_homestory_N26dianying_90060201_109_dialog_content = "Jajajaja! ¡Así que finalmente decidiste aparecer!",
  str_homestory_N26dianying_90060201_110_dialog_content = "Has venido a ponerte en contacto conmigo, ¿sí?",
  str_homestory_N26dianying_90060201_111_dialog_content = "¡E-Eso es correcto! ¡Perdón por llegar tan tarde!",
  str_homestory_N26dianying_90060201_112_dialog_content = "No pienses nada de eso. Mientras desees formar parte de mi tripulación, puedo pasarlo por alto por una vez.",
  str_homestory_N26dianying_90060201_113_dialog_content = "¡Ay, no te preocupes por eso!",
  str_homestory_N26dianying_90060201_114_dialog_content = "Ahora bien... ¡Bienvenido a bordo, mi nuevo miembro de la tripulación!",
  str_homestory_N26dianying_90060201_115_dialog_content = "¿C-Equipo?",
  str_homestory_N26dianying_90060201_116_dialog_content = "En efecto. Y como fuiste el primero en llegar, tienes el privilegio de ser mi primer oficial.",
  str_homestory_N26dianying_90060201_117_dialog_content = "A partir de ahora, puedes referirte a mí como \"patrón\".",
  str_homestory_N26dianying_90060201_118_dialog_content = "En efecto. Y como fuiste el primero en llegar, tienes el privilegio de ser mi primer oficial.",
  str_homestory_N26dianying_90060201_119_dialog_content = "A partir de ahora, puedes referirte a mí como \"patrón\".",
  str_homestory_N26dianying_90060201_120_dialog_content = "Espera, espera, espera... Creo que ha habido algún tipo de malentendido otra vez...",
  str_homestory_N26dianying_90060201_121_dialog_content = "¿Qué tipo de capitán eres, exactamente? Estamos completamente encerrados aquí, ¡y no se ve un barco en miles de millas!",
  str_homestory_N26dianying_90060201_122_dialog_content = "¿También te das cuenta, entonces? Este lugar sufre una grave escasez de embarcaciones de navegación...",
  str_homestory_N26dianying_90060201_123_dialog_content = "¡Pero si logro construir un barco aquí, seré el primer patrón en toda la ciudad! Un prestigioso honor, ¿no le parece?",
  str_homestory_N26dianying_90060201_124_dialog_content = "¿También te das cuenta, entonces? Este lugar sufre una grave escasez de embarcaciones de navegación...",
  str_homestory_N26dianying_90060201_125_dialog_content = "¡Pero si logro construir un barco aquí, seré el primer patrón en toda la ciudad! Un prestigioso honor, ¿no le parece?",
  str_homestory_N26dianying_90060201_126_dialog_content = "Bueno, por mucho que admiro tu espíritu pionero...",
  str_homestory_N26dianying_90060201_127_dialog_content = "¿No crees que la falta de barcos tiene algo que ver con, no sé... la falta de un cuerpo de agua?",
  str_homestory_N26dianying_90060201_128_dialog_content = "Je... Un barco NO NECESITA agua para navegar.",
  str_homestory_N26dianying_90060201_129_dialog_content = "Je... Un barco NO NECESITA agua para navegar.",
  str_homestory_N26dianying_90060201_130_dialog_content = "¡¿Qué diablos se supone que significa eso?!",
  str_homestory_N26dianying_90060201_131_dialog_content = "Tenga la seguridad de que he tenido en cuenta todas estas preguntas.",
  str_homestory_N26dianying_90060201_132_dialog_content = "Tenga la seguridad de que he tenido en cuenta todas estas preguntas.",
  str_homestory_N26dianying_90060201_133_dialog_content = "¿En serio? ¡Porque discrepo!",
  str_homestory_N26dianying_90060201_134_dialog_content = "Una vez que suficientes personas se unan a nuestro equipo, ¡podemos pedirle al reino su apoyo! ¡Todo saldrá bien una vez que lleguemos a ese punto!",
  str_homestory_N26dianying_90060201_135_dialog_content = "Una vez que suficientes personas se unan a nuestro equipo, ¡podemos pedirle al reino su apoyo! ¡Todo saldrá bien una vez que lleguemos a ese punto!",
  str_homestory_N26dianying_90060201_136_dialog_content = "... ¿Sabes que? ¡Acabo de recordar que me mareo muy fácilmente! ¡Además, tengo otros asuntos que atender!",
  str_homestory_N26dianying_90060201_137_dialog_content = "¡Me iré ahora!",
  str_homestory_N26dianying_90060201_138_dialog_content = "Pero espera, ¿qué hay de ser mi primer oficial?",
  str_homestory_N26dianying_90060201_139_dialog_content = "Pero espera, ¿qué hay de ser mi primer oficial?",
  str_homestory_N26dianying_90060201_140_dialog_content = "Realmente no estoy hecho para la vida de capa y espada, ¡lo prometo! ¡La mejor de las suertes!",
  str_homestory_N26dianying_90060201_141_dialog_content = "Cielos... ¡¿Hay una sola persona normal en este lugar?!",
  str_homestory_N26dianying_90060201_142_dialog_content = "Quién más podría ser...?",
  str_homestory_N26dianying_90060201_143_dialog_content = "Oh no... Solo hay una persona a la que no le he preguntado todavía.",
  str_homestory_N26dianying_90060201_144_dialog_content = "Pero no coinciden en absoluto con la descripción de la misión... ¿Qué debo hacer?",
  str_homestory_N26dianying_90060201_145_dialog_content = "Ah, olvídalo... Ya estoy aquí, así que también puedo intentarlo.",
  str_homestory_N26dianying_90060201_146_dialog_content = "¡Posadero! ¡Una olla más, por favor!",
  str_homestory_N26dianying_90060201_147_dialog_content = "Muy bien, pero... Sabes que este es tu tercer bote, ¿verdad?",
  str_homestory_N26dianying_90060201_148_dialog_content = "No sabía que te gustaba tanto el vino osmanthus.",
  str_homestory_N26dianying_90060201_149_dialog_content = "T-Para ser honesto, ni siquiera he tomado un sorbo de las cosas...",
  str_homestory_N26dianying_90060201_150_dialog_content = "Por favor, deje que este cliente de aspecto extraño sea la persona que estoy buscando...",
  str_homestory_N26dianying_90060201_151_dialog_content = "Perdóneme, pero ¿le gustaría...?",
  str_homestory_N26dianying_90060201_152_dialog_content = "¡Por fin estás aquí!",
  str_homestory_N26dianying_90060201_153_dialog_content = "¡¿Eh?!",
  str_homestory_N26dianying_90060201_154_dialog_content = "L-Lo siento, tu respuesta me tomó por sorpresa...",
  str_homestory_N26dianying_90060201_155_dialog_content = "Sabes quién soy, ¿verdad?",
  str_homestory_N26dianying_90060201_156_dialog_content = "Yo hago? Lo siento, pero ya no puedo estar seguro de nada...",
  str_homestory_N26dianying_90060201_157_dialog_content = "Las últimas dos personas a las que me acerqué eran... otra cosa.",
  str_homestory_N26dianying_90060201_158_dialog_content = "¡Vengo de mil años en el futuro!",
  str_homestory_N26dianying_90060201_159_dialog_content = "¡¡¡Y tú no eres diferente!!!",
  str_homestory_N26dianying_90060201_160_dialog_content = "Me quedé varado en este punto después de que un error de entrada hiciera que mi teletransportador fallara gravemente.",
  str_homestory_N26dianying_90060201_161_dialog_content = "Pero estás aquí para llevarme de vuelta, ¿verdad?",
  str_homestory_N26dianying_90060201_162_dialog_content = "... No entendí ni una sola palabra de lo que salió de tu boca hace un momento.",
  str_homestory_N26dianying_90060201_163_dialog_content = "Espera, ¿entonces NO vas a llevarme de vuelta a mi tiempo? Aburrido.",
  str_homestory_N26dianying_90060201_164_dialog_content = "¡Aaargh! ¡He fallado completamente en mi búsqueda!",
  str_homestory_N26dianying_90060201_165_dialog_content = "¿Búsqueda?",
  str_homestory_N26dianying_90060201_166_dialog_content = "¿Búsqueda? ¿Qué búsqueda?",
  str_homestory_N26dianying_90060201_167_dialog_content = "Oh, olvídalo... Ya no importa.",
  str_homestory_N26dianying_90060201_168_dialog_content = "Lo siento, pero no soy la persona que estás buscando.",
  str_homestory_N26dianying_90060201_169_dialog_content = "Aún así, tengo que preguntar... ¿Qué hace alguien del futuro en un lugar como este?",
  str_homestory_N26dianying_90060201_170_dialog_content = "Mil años en el futuro, mi laboratorio está ubicado en este mismo lugar.",
  str_homestory_N26dianying_90060201_171_dialog_content = "¡Eso es porque mi laboratorio está sentado en este lugar exacto! Solo mil años en el futuro, por supuesto.",
  str_homestory_N26dianying_90060201_172_dialog_content = "De todos modos, mis compañeros investigadores deberían estar aquí para rescatarme lo suficientemente pronto... En cualquier momento.",
  str_homestory_N26dianying_90060201_173_dialog_content = "¿Es por eso que has estado esperando aquí todo este tiempo? ¿No hay otra forma de volver a tu tiempo?",
  str_homestory_N26dianying_90060201_174_dialog_content = "Bueno, ¿podría esperar otros mil años?",
  str_homestory_N26dianying_90060201_175_dialog_content = "No realmente. No puedo contactar a mis colegas en absoluto desde este momento.",
  str_homestory_N26dianying_90060201_176_dialog_content = "Si no puedo alcanzarlos, tendré que esperar hasta que el laboratorio se construya de nuevo.",
  str_homestory_N26dianying_90060201_177_dialog_content = "¡¿Te vas a sentar aquí por un milenio?!",
  str_homestory_N26dianying_90060201_178_dialog_content = "Si eso es lo que se necesita, entonces sí.",
  str_homestory_N26dianying_90060201_179_dialog_content = "Eso es, eh... Requerirá mucha paciencia.",
  str_homestory_N26dianying_90060201_180_dialog_content = "Suspiro... ¡Si tan solo mi héroe tuviera ese tipo de paciencia!",
  str_homestory_N26dianying_90060201_181_dialog_content = "Aún así, no los culpo por no estar aquí. En todo caso, es mi culpa por llegar tan tarde...",
  str_homestory_N26dianying_90060201_182_dialog_content = "¿Siempre podrías pasar los próximos mil años haciéndome compañía?",
  str_homestory_N26dianying_90060201_183_dialog_content = "Vaya, gracias por la amable oferta...",
  str_homestory_N26dianying_90060201_184_dialog_content = "Ojalá pudiera ser tan optimista sobre las cosas como tú...",
  str_homestory_N26dianying_90060201_185_dialog_content = "¡Oye! ¡Escuchad, cerdos complacientes!",
  str_homestory_N26dianying_90060201_186_dialog_content = "¿Eh? ¿Qué pasa con todos los gritos afuera?",
  str_homestory_N26dianying_90060201_187_dialog_content = "Esta montaña me pertenece, ¿oíste?",
  str_homestory_N26dianying_90060201_188_dialog_content = "Si tienes algo de cerebro entre las orejas, ¡deja tus objetos de valor y piérdete! ¡Si no lo haces, aplastaré el pequeño cerebro que tienes en el suelo!",
  str_homestory_N26dianying_90060201_189_dialog_content = "¡¿Bandidos?! ¡Ay, esto es malo!",
  str_homestory_N26dianying_90060201_190_dialog_content = "¡No soy rival para todos ellos a la vez! Tengo que encontrar una manera de salir de aquí...",
  str_homestory_N26dianying_90060201_191_dialog_content = "Maldición... Si lucho contra ellos, mi tapadera será descubierta. Hora de retirarse...",
  str_homestory_N26dianying_90060201_192_dialog_content = "¡¡Eso fue rápido!!",
  str_homestory_N26dianying_90060201_193_dialog_content = "¡Oh, genial! ¡Solo mira todas esas caras ansiosas! ¡Deben haber venido a unirse a mi tripulación!",
  str_homestory_N26dianying_90060201_194_dialog_content = "¡Debería ir a saludarlos!",
  str_homestory_N26dianying_90060201_195_dialog_content = "¡Oh, genial! ¡Solo mira todas esas caras ansiosas! ¡Deben haber venido a unirse a mi tripulación!",
  str_homestory_N26dianying_90060201_196_dialog_content = "¡Debería ir a saludarlos!",
  str_homestory_N26dianying_90060201_197_dialog_content = "¡G-Vuelve aquí! ¡¿No tienes ni el más mínimo control sobre la realidad?!",
  str_homestory_N26dianying_90060201_198_dialog_content = "Esto no servirá... No puedo permitir que una horda de bandidos se apodere del futuro sitio del laboratorio.",
  str_homestory_N26dianying_90060201_199_dialog_content = "Iré a exterminarlos.",
  str_homestory_N26dianying_90060201_200_dialog_content = "¿Por tí mismo? ¡Pero parece que hay un montón de ellos por ahí!",
  str_homestory_N26dianying_90060201_201_dialog_content = "Wow... Solo así, los únicos que quedan aquí somos el posadero y yo...",
  str_homestory_N26dianying_90060201_202_dialog_content = "Simplemente, este no es mi día... Primero no logro contactar con la persona adecuada, luego somos atacados por bandidos...",
  str_homestory_N26dianying_90060201_203_dialog_content = "¿Todavía tengo que pagar mi cuenta si todos terminamos muertos?",
  str_homestory_N26dianying_90060201_204_dialog_content = "Así que has renunciado a tu búsqueda, ¿verdad?",
  str_homestory_N26dianying_90060201_205_dialog_content = "Sí... Supongo que es hora de aceptar mi destino...",
  str_homestory_N26dianying_90060201_206_dialog_content = "E-Espera, ¡¿cómo supiste eso?!",
  str_homestory_N26dianying_90060201_207_dialog_content = "¡Se supone que mi búsqueda es ultrasecreta!",
  str_homestory_N26dianying_90060201_208_dialog_content = "La persona que estabas buscando estuvo aquí todo el tiempo...",
  str_homestory_N26dianying_90060201_209_dialog_content = "Pero eso no necesariamente los convertía en clientes.",
  str_homestory_N26dianying_90060201_210_dialog_content = "Espera, no querrás decir...",
  str_homestory_N26dianying_90060201_211_dialog_content = "Podría ser...?!",
  str_homestory_N26dianying_90060201_212_dialog_content = "¿Eres TÚ el guerrero que se supone que debo conocer?",
  str_homestory_N26dianying_90060201_213_dialog_content = "¡De ninguna manera! ¡Esto no puede ser!",
  str_homestory_N26dianying_90060201_214_dialog_content = "¡Se supone que la persona en la búsqueda está \"en la plenitud de su vida\"! ¡Se supone que sus artes marciales son insuperables! Pero tu...",
  str_homestory_N26dianying_90060201_215_dialog_content = "Tu rostro está tan desgastado... ¡Y estás confinado a una silla de ruedas! ¿Cómo puedes ser la persona que estoy buscando?",
  str_homestory_N26dianying_90060201_216_dialog_content = "Je, una descripción bastante fantasiosa... Pero encaja, de todos modos. El guerrero que viniste a buscar no es otro que tuyo de verdad.",
  str_homestory_N26dianying_90060201_217_dialog_content = "Sólo... Llegaste demasiado tarde.",
  str_homestory_N26dianying_90060201_218_dialog_content = "¡Diez años demasiado tarde, de hecho!",
  str_homestory_N26dianying_90060201_219_dialog_content = "¡¿Diez años?!",
  str_homestory_N26dianying_90060201_220_dialog_content = "¿¡¿Qué?!?",
  str_homestory_N26dianying_90060201_221_dialog_content = "Mis piernas fueron gravemente heridas hace diez años, así que me escondí aquí. He estado esperando que un héroe me traiga un elixir curativo.",
  str_homestory_N26dianying_90060201_222_dialog_content = "Pero no importa cuánto tiempo esperé... Ese héroe nunca llegó.",
  str_homestory_N26dianying_90060201_223_dialog_content = "Mucho ha cambiado en los últimos diez años. Me obligué a beber vino osmanthus todos los días y, finalmente, desarrollé el gusto por él.",
  str_homestory_N26dianying_90060201_224_dialog_content = "Debido a que el elixir nunca llegó, mis piernas empeoraron gradualmente y terminé en una silla de ruedas.",
  str_homestory_N26dianying_90060201_225_dialog_content = "Me hice muy amigo del dueño anterior de esta posada, y cuando finalmente falleció... Me sorprendió saber que me la había confiado.",
  str_homestory_N26dianying_90060201_226_dialog_content = "Nunca esperé que, después de todo este tiempo, aún aparecieras.",
  str_homestory_N26dianying_90060201_227_dialog_content = "Oh, eh...",
  str_homestory_N26dianying_90060201_228_option_content = "disculparme sinceramente",
  str_homestory_N26dianying_90060201_229_dialog_content = "¡No te quedes ahí parado! ¡Discúlpate, ahora mismo!",
  str_homestory_N26dianying_90060201_230_dialog_content = "¡P-Perdóname, valiente héroe! ¡Desde el fondo de mi corazón, lo siento muchísimo!",
  str_homestory_N26dianying_90060201_231_dialog_content = "S-si tan solo no llegara tan tarde...",
  str_homestory_N26dianying_90060201_232_dialog_content = "¿Llegaste diez años \"tarde\"? ¿No crees que es un poco subestimar?",
  str_homestory_N26dianying_90060201_233_dialog_content = "Todo es culpa mía... Perdí el pergamino de misión en algún lugar de mi casa...",
  str_homestory_N26dianying_90060201_234_dialog_content = "No fue hasta que comencé a empacar para mudarme que finalmente lo encontré. El único problema fue que olvidé la antigüedad de la solicitud...",
  str_homestory_N26dianying_90060201_235_dialog_content = "Está bien. Si esto hubiera sucedido hace unos años, podría haber estado molesto, pero ahora... no puedo evitar encontrarlo divertido. Risible, incluso.",
  str_homestory_N26dianying_90060201_236_dialog_content = "Pareces ser completamente sincero, así que no seguiré con el asunto. Mis días de aventuras han quedado muy atrás; Solo deseo pasar el resto de mi vida en paz.",
  str_homestory_N26dianying_90060201_237_dialog_content = "Aún así, dejé bastantes asuntos sin terminar en el pasado... Si realmente deseas hacer las paces, ¿podrías encargarte de ellos en mi lugar?",
  str_homestory_N26dianying_90060201_238_dialog_content = "¿En serio? ¡Por supuesto, estaría más que dispuesto a ayudar!",
  str_homestory_N26dianying_90060201_239_dialog_content = "Un viejo compañero mío de mis días de aventuras vive cerca. Al igual que yo, ha optado por mantener oculta su identidad y trabaja en el mercado.",
  str_homestory_N26dianying_90060201_240_dialog_content = "Tengo una carta para él, y quiero que cumplas mi misión entregándosela.",
  str_homestory_N26dianying_90060201_241_dialog_content = "¡Entendí! Solo tengo que reunirme con otro contacto anónimo, ¿verdad? ¡Definitivamente tengo experiencia con este tipo de misiones ahora!",
  str_homestory_N26dianying_90060201_242_dialog_content = "Ciertamente lo espero.",
  str_homestory_N26dianying_90060201_243_dialog_content = "No hay lugar para más de su \"tardanza\" a la hora de entregar esta carta.",
  str_homestory_N26dianying_90060201_244_dialog_content = "La persona en cuestión es incluso mayor que yo. Dudo que viva para ver pasar otra década.",
  str_homestory_N26dianying_90060201_245_option_content = "Inventar una excusa",
  str_homestory_N26dianying_90060201_246_dialog_content = "¿Has olvidado? ¡Piensa en la razón por la que llegaste tan tarde!",
  str_homestory_N26dianying_90060201_247_dialog_content = "¡Correcto! ¡Es porque tenía demasiadas misiones en mis manos!",
  str_homestory_N26dianying_90060201_248_dialog_content = "Verás, con la tierra en tal estado de desorden, ¡tenía tantos héroes acercándose a mí que no podía seguirles la pista a todos!",
  str_homestory_N26dianying_90060201_249_dialog_content = "Algunos de ellos ya estaban al borde de la muerte, así que tuve que priorizarlos.",
  str_homestory_N26dianying_90060201_250_dialog_content = "U-Desafortunadamente... Es por eso que me tomó tanto tiempo ir a buscarte.",
  str_homestory_N26dianying_90060201_251_dialog_content = "¿Es eso así? No tenía idea de que había tantos héroes en apuros...",
  str_homestory_N26dianying_90060201_252_dialog_content = "¿Por qué no me nombras algunos de ellos? Quién sabe, tal vez los conocí en mi época.",
  str_homestory_N26dianying_90060201_253_dialog_content = "Me sentiría mucho mejor sabiendo que mis viejos camaradas fueron atendidos, incluso si fue por mi propia cuenta.",
  str_homestory_N26dianying_90060201_254_dialog_content = "S-Claro, solo un momento...",
  str_homestory_N26dianying_90060201_255_dialog_content = "Toma todo el tiempo que necesites. Después de todo, esperé diez años por ti... Podría esperar diez más.",
  str_homestory_N26dianying_90060201_256_dialog_content = "Si no puede recordar sus nombres, entonces tal vez podría presentarle a algunos de ellos. Eso podría refrescarte la memoria...",
  str_homestory_N26dianying_90060201_257_dialog_content = "¿Preséntame a ellos?",
  str_homestory_N26dianying_90060201_258_dialog_content = "Así es, aunque ya no debería llamarlos \"héroes\". Verás, algunos de ellos comenzaron a ir por el camino equivocado en el pasado...",
  str_homestory_N26dianying_90060201_259_dialog_content = "De hecho, creo que algunos de ellos están parados justo afuera de mi puerta, esperando la oportunidad de hablar sobre los buenos viejos tiempos.",
  str_homestory_N26dianying_90060201_260_dialog_content = "No te refieres a los bandidos... ¿o sí?",
  str_homestory_N26dianying_90060201_261_dialog_content = "¡No por favor! ¡No quiero conocerlos!",
  str_homestory_N26dianying_90060201_262_dialog_content = "¡Me equivoqué, señor tabernero! ¡¡¡Lo siento!!!",
  str_homestory_N26dianying_90060201_263_option_content = "Completa la misión",
  str_homestory_N26dianying_90060201_264_dialog_content = "¡No lo olvides! ¡Aún tienes una misión por completar!",
  str_homestory_N26dianying_90060201_265_dialog_content = "¡Nada de eso importa ahora! ¡Te he traído el elixir que pediste, valiente héroe!",
  str_homestory_N26dianying_90060201_266_dialog_content = "Y aunque me retrasé un poco con la entrega... ¡Mi búsqueda finalmente está completa!",
  str_homestory_N26dianying_90060201_267_dialog_content = "\"Un poco tarde\", dices?",
  str_homestory_N26dianying_90060201_268_dialog_content = "No tenía idea de que una década fuera una cantidad de tiempo tan insignificante...",
  str_homestory_N26dianying_90060201_269_dialog_content = "Lo siento mucho por eso... Es solo que perdí el pergamino de búsqueda en algún lugar de mi casa...",
  str_homestory_N26dianying_90060201_270_dialog_content = "No fue hasta que comencé a empacar para mudarme que finalmente lo encontré. El único problema fue que olvidé la antigüedad de la solicitud...",
  str_homestory_N26dianying_90060201_271_dialog_content = "En cualquier caso, lo traje hasta aquí, así que aquí tienes. Quién sabe, ¡quizás te arregle las piernas!",
  str_homestory_N26dianying_90060201_272_dialog_content = "De esta manera, puedo entregar mi búsqueda cuando regrese.",
  str_homestory_N26dianying_90060201_273_dialog_content = "Ya no lo necesito. Mis piernas están acabadas, y ninguna cantidad de elixir podría repararlas.",
  str_homestory_N26dianying_90060201_274_dialog_content = "Solo guárdalo para ti. Podrías terminar necesitándolo algún día.",
  str_homestory_N26dianying_90060201_275_dialog_content = "No sé sobre eso... Además, no puedo entregar mi misión si no la aceptas.",
  str_homestory_N26dianying_90060201_276_dialog_content = "Bueno, resulta que estamos rodeados por un grupo de bandidos sedientos de sangre...",
  str_homestory_N26dianying_90060201_277_dialog_content = "Creo que podrías necesitarlo más de lo que crees muy pronto.",
  str_homestory_N26dianying_90060201_278_dialog_content = "¿¡¿Qué?!?",
  str_homestory_N26dianying_90060201_279_dialog_content = "¡No por favor! ¡Sálvame, héroe grande y misericordioso!",
  str_homestory_N26dianying_90060201_280_dialog_content = "¡Posadero! ¡Una jarra de su mejor vino osmanthus, por favor!",
  str_homestory_N26dianying_90060201_281_dialog_content = "Lo siento, pero estamos todos fuera.",
  str_homestory_N26dianying_90060201_282_dialog_content = "¿Qué? \"Completamente\"?!",
  str_homestory_N26dianying_90060201_283_dialog_content = "Así es. En este momento no tengo ni una gota del material disponible.",
  str_homestory_N26dianying_90060201_284_dialog_content = "¿Cómo pudiste salir corriendo en un momento como este? ¡Todo está arruinado ahora!",
  str_homestory_N26dianying_90060201_285_dialog_content = "Siempre puedo enviar por algunos, si quieres.",
  str_homestory_N26dianying_90060201_286_dialog_content = "Si tiene tantas ganas de tomar este tipo de vino hoy, puedo pedirlo en una tienda vecina. Tomará algún tiempo, pero se puede hacer.",
  str_homestory_N26dianying_90060201_287_dialog_content = "¿D-De veras?",
  str_homestory_N26dianying_90060201_288_dialog_content = "¡Bien, puedo esperar!",
  str_homestory_N26dianying_90060201_289_dialog_content = "Este vino osmanthus tiene un sabor muy singular. No mucha gente bebe esto hoy en día, pero disfrútalo.",
  str_homestory_N26dianying_90060201_290_dialog_content = "Aún así, me alegra el corazón ver a alguien más que aprecia mi bebida favorita.",
  str_homestory_N26dianying_90060201_291_dialog_content = "Póngalo a un lado cuando llegue aquí, por favor. Todo se arruinará si no tengo una olla...",
  str_homestory_N26dianying_90060201_292_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc!</color>",
  str_homestory_N26dianying_90060201_293_dialog_content = "¡Alguien está en la puerta! ¿Trajeron el vino osmanthus?",
  str_homestory_N26dianying_90060201_294_dialog_content = "¡Shhh! Esta voz...",
  str_homestory_N26dianying_90060201_295_dialog_content = "¡Oye! ¡Escuchad, cerdos complacientes!",
  str_homestory_N26dianying_90060201_296_dialog_content = "Esta montaña me pertenece, ¿oíste?",
  str_homestory_N26dianying_90060201_297_dialog_content = "Si tienes algo de cerebro entre las orejas, ¡deja tus objetos de valor y piérdete! ¡Si no lo haces, aplastaré el pequeño cerebro que tienes en el suelo!",
  str_homestory_N26dianying_90060201_298_dialog_content = "¿Bandidos? Ahora, de todos los tiempos?!",
  str_homestory_N26dianying_90060201_299_dialog_content = "Maldición... Si lucho contra ellos, mi tapadera será descubierta. Hora de retirarse...",
  str_homestory_N26dianying_90060201_300_dialog_content = "¡Oh, genial! ¡Iré a saludarlos!",
  str_homestory_N26dianying_90060201_301_dialog_content = "¡Oh, genial! ¡Iré a saludarlos!",
  str_homestory_N26dianying_90060201_302_dialog_content = "Exterminarlos a todos.",
  str_homestory_N26dianying_90060201_303_dialog_content = "Desafortunadamente, parece que mi humilde posada está a punto de ser saqueada por una banda de bandidos.",
  str_homestory_N26dianying_90060201_304_dialog_content = "Ahora bien, si fueras tan amable de escapar por la parte de atrás...",
  str_homestory_N26dianying_90060201_305_dialog_content = "Bueno, me encantaría escapar con mi vida y todo...",
  str_homestory_N26dianying_90060201_306_dialog_content = "¡¿Pero qué pasa con mi búsqueda?!",
  str_homestory_N26dianying_90060301_1_dialog_content = "Las llamas de la guerra han devastado nuestro mundo durante muchos años... Con cada día que pasa, nuestra lucha contra los Eclipsites parece más y más desesperada.",
  str_homestory_N26dianying_90060301_2_dialog_content = "Solo la Heavenly Blade perdida hace mucho tiempo, un arma sagrada y poderosa, puede poner fin a la lucha y traer la paz al mundo una vez más.",
  str_homestory_N26dianying_90060301_3_dialog_content = "... O eso dice la leyenda. ¿No es así, mi fiel servidor?",
  str_homestory_N26dianying_90060301_4_dialog_content = "<size=45>¡Si mi señor!</size>",
  str_homestory_N26dianying_90060301_5_dialog_content = "¡Argh, mis oídos! ¡Baja la voz, tonto!",
  str_homestory_N26dianying_90060301_6_dialog_content = "Ejem... Como enviado de Dragonscorch, la fuerza más poderosa de la tierra, tengo mis razones para convocarte aquí hoy.",
  str_homestory_N26dianying_90060301_7_dialog_content = "A pesar de que te has unido recientemente a nuestra facción, ya has demostrado que eres un sirviente leal y capaz.",
  str_homestory_N26dianying_90060301_8_dialog_content = "Ahora bien, la leyenda también dice que la Espada Celestial fue vista por última vez en la Aldea de los Dragones. Por lo que entiendo, también eres del mismo pueblo, ¿no es así?",
  str_homestory_N26dianying_90060301_9_dialog_content = "<size=45>¡Si mi señor!</size>",
  str_homestory_N26dianying_90060301_10_dialog_content = "Excelente... Entonces, por la presente, te confío un deber sagrado: regresa a la Aldea de los Dragones y encuentra la Espada Celestial en mi lugar.",
  str_homestory_N26dianying_90060301_11_dialog_content = "¡Tenga la seguridad, mi señor, que no le fallaré!",
  str_homestory_N26dianying_90060301_12_dialog_content = "Ahora son las 11:15 de la mañana... A partir de ahora, tienes exactamente tres días para encontrar la hoja y traérmela.",
  str_homestory_N26dianying_90060301_13_dialog_content = "(Espera... ¡¿Dijo \"11:15\"?!)",
  str_homestory_N26dianying_90060301_14_dialog_content = "¿Eh, mi señor? Yo, eh... ¡Acabo de darme cuenta de que todavía necesito empacar algunos suministros antes de partir en mi noble misión!",
  str_homestory_N26dianying_90060301_15_dialog_content = "Muy bien entonces. Ocúpate de tus provisiones y sigue tu camino, ¡pero hazlo rápido!",
  str_homestory_N26dianying_90060301_16_dialog_content = "Jadeo, jadeo, jadeo...",
  str_homestory_N26dianying_90060301_17_dialog_content = "M-Maestro! Mis disculpas por el ligero retraso!",
  str_homestory_N26dianying_90060301_18_dialog_content = "\"Ligero\", dices? Llegas treinta minutos tarde.",
  str_homestory_N26dianying_90060301_19_dialog_content = "Suspiro... No importa. Te he convocado hoy porque necesito tu ayuda con un asunto de suma importancia.",
  str_homestory_N26dianying_90060301_20_dialog_content = "Seguramente, ¿has escuchado la leyenda de Heavenly Blade? \"Las llamas de la guerra han devastado nuestro mundo durante muchos años...\"",
  str_homestory_N26dianying_90060301_21_dialog_content = "Mi señor, podría ser que... ¿También desea que vaya a la Aldea de los Dragones en busca de la Espada Celestial?",
  str_homestory_N26dianying_90060301_22_dialog_content = "Eso es correcto. Al encontrar Heavenly Blade, la facción Zakura traerá orden a este mundo caótico y consolidará su lugar como la fuerza más poderosa que existe.",
  str_homestory_N26dianying_90060301_23_dialog_content = "Espera... ¿Qué quieres decir con \"también\"?",
  str_homestory_N26dianying_90060301_24_dialog_content = "¡Vaya! ¡N-Nada, mi señor!",
  str_homestory_N26dianying_90060301_25_dialog_content = "(Si los enviados de ambas facciones se enteran de que estoy realizando la misma misión para ellos...)",
  str_homestory_N26dianying_90060301_26_dialog_content = "(¡Seré tan bueno como muerto!)",
  str_homestory_N26dianying_90060301_27_dialog_content = "Si bien todavía te falta experiencia, mis fuentes me dicen que la hoja se puede encontrar en algún lugar de tu ciudad natal, Village of Dragons. Eres la única persona en la que puedo confiar con esta misión.",
  str_homestory_N26dianying_90060301_28_dialog_content = "<size=45>¡Si mi señor!</size>",
  str_homestory_N26dianying_90060301_29_dialog_content = "H-Sin embargo, todavía tengo algunas cosas que discutir con mis camaradas antes de partir...",
  str_homestory_N26dianying_90060301_30_dialog_content = "Muy bien, pero trate de ser breve. Ah, y recuerda comprobar el tiempo por mí antes de irte.",
  str_homestory_N26dianying_90060301_31_dialog_content = "Jadeo, jadeo, jadeo...",
  str_homestory_N26dianying_90060301_32_dialog_content = "¡M-Mi señor! ¡Hoy hace buen tiempo, un día perfecto para entrenar a tus soldados!",
  str_homestory_N26dianying_90060301_33_dialog_content = "¿Mmm? No recuerdo haberte pedido un informe meteorológico.",
  str_homestory_N26dianying_90060301_34_dialog_content = "(¡Oh, mierda! ¡Señor equivocado!)",
  str_homestory_N26dianying_90060301_35_dialog_content = "Si ha terminado con sus preparativos, ¡salga inmediatamente! ¡Si tienes éxito, tus recompensas serán abundantes!",
  str_homestory_N26dianying_90060301_36_dialog_content = "Ah, y si ves los girasoles floreciendo durante tu viaje, encuentra una manera de enviarme un mensaje. ¿Entendí?",
  str_homestory_N26dianying_90060301_37_dialog_content = "¡Si mi señor! ¡Me iré enseguida!",
  str_homestory_N26dianying_90060301_38_dialog_content = "Jadeo, jadeo, jadeo...",
  str_homestory_N26dianying_90060301_39_dialog_content = "¡He vuelto, mi señor! ¡Los girasoles están floreciendo y llenos de semillas! ¡Se pueden recolectar en cualquier momento para las raciones de los soldados!",
  str_homestory_N26dianying_90060301_40_dialog_content = "¿Mmm? ¿Y cuándo exactamente pedí un informe sobre los girasoles?",
  str_homestory_N26dianying_90060301_41_dialog_content = "Ah, y durante tu viaje, si notas que los juncos han crecido, encuentra la manera de enviarme un mensaje. ¿Entendí?",
  str_homestory_N26dianying_90060301_42_dialog_content = "¡Si mi señor! ¡Me iré enseguida!",
  str_homestory_N26dianying_90060301_43_dialog_content = "Jadeo, jadeo, jadeo...",
  str_homestory_N26dianying_90060301_44_dialog_content = "¡He vuelto, mi señor! Los juncos son altos y densos ahora, ¡perfectos para ocultar un ataque sorpresa a tus enemigos!",
  str_homestory_N26dianying_90060301_45_dialog_content = "¿Vaya? ¿Y cuándo exactamente pedí un informe sobre las cañas?",
  str_homestory_N26dianying_90060301_46_dialog_content = "Ah, y durante tu viaje, si notas que los campos de trigo han alcanzado la madurez completa, encuentra la manera de enviarme un mensaje. ¿Entendí?",
  str_homestory_N26dianying_90060301_47_dialog_content = "¡Si mi señor! ¡Me iré enseguida!",
  str_homestory_N26dianying_90060301_48_dialog_content = "Jadeo, jadeo, jadeo...",
  str_homestory_N26dianying_90060301_49_dialog_content = "¡He vuelto, mi señor! ¡Los campos de trigo están llenos y listos para la cosecha! ¡Los soldados comerán bien este invierno!",
  str_homestory_N26dianying_90060301_50_dialog_content = "¿Vaya? ¿Y cuándo exactamente pedí un informe sobre los campos de trigo?",
  str_homestory_N26dianying_90060301_50X1_dialog_content = "Ah, y durante su viaje, si nota a alguna persona sospechosa, encuentre una manera de enviarme un mensaje. ¿Entendí?",
  str_homestory_N26dianying_90060301_50X2_dialog_content = "¡Si mi señor! ¡Me iré enseguida!",
  str_homestory_N26dianying_90060301_50X3_dialog_content = "Jadeo, jadeo, jadeo...",
  str_homestory_N26dianying_90060301_50X4_dialog_content = "¡He vuelto, mi señor! No hay personas sospechosas cerca. ¡Podemos empezar a prepararnos para el entrenamiento!",
  str_homestory_N26dianying_90060301_50X5_dialog_content = "¿Mmm? ¡No recuerdo haberte pedido que me informaras de la situación cercana!",
  str_homestory_N26dianying_90060301_51_dialog_content = "(¡Mierda! ¡¡No otra vez!!)",
  str_homestory_N26dianying_90060301_52_dialog_content = "Si ha terminado de despedirse de sus amigos, diríjase a la Aldea de los Dragones. Tendrás mi eterna gratitud si tienes éxito en tu búsqueda.",
  str_homestory_N26dianying_90060301_53_dialog_content = "¡Si mi señor! ¡Me iré enseguida!",
  str_homestory_N26dianying_90060301_54_dialog_content = "(Mis señores, ustedes son hombres sabios y poderosos... ¡Así que por favor perdónenme!)",
  str_homestory_N26dianying_90060301_55_dialog_content = "(Dos recompensas por el precio de una misión... ¡Es demasiado bueno para dejarlo pasar!)",
  str_homestory_N26dianying_90060301_56_dialog_content = "Vaya... Finalmente llegué a la Aldea de los Dragones. Esto realmente me recuerda...",
  str_homestory_N26dianying_90060301_57_dialog_content = "¡Acércate y echa un vistazo! Armas maravillosas de todo el mundo! ¡Espadas sagradas y cuchillas en abundancia, todo con descuentos increíbles!",
  str_homestory_N26dianying_90060301_58_dialog_content = "¡Llegado uno viene todos! Tengo todo tipo de espadas sagradas a la venta aquí, ¡pero mis conchas de agua bendita son las verdaderas estrellas del espectáculo!",
  str_homestory_N26dianying_90060301_59_dialog_content = "¿Qué? Lo siento, ¿dijiste que tenías espadas sagradas a la venta?",
  str_homestory_N26dianying_90060301_60_dialog_content = "Si eso es lo que estás buscando, ¡entonces has venido al lugar correcto! Diablos, incluso tengo Heavenly Blade en stock, si estás interesado.",
  str_homestory_N26dianying_90060301_61_dialog_content = "¿Ves esa espada en el estante de armas de allí? ¡Estaría dispuesto a deshacerme de él por el bajo precio de 99,999,999 Nightium!",
  str_homestory_N26dianying_90060301_62_dialog_content = "Si eso es lo que estás buscando, ¡entonces has venido al lugar correcto! Diablos, incluso tengo Heavenly Blade en stock, si estás interesado.",
  str_homestory_N26dianying_90060301_63_dialog_content = "¿Ves esa espada en el estante de armas de allí? ¡Estaría dispuesto a deshacerme de él por el bajo precio de 99,999,999 Nightium!",
  str_homestory_N26dianying_90060301_64_dialog_content = "¡Eso es tan caro! ¿Podría ser realmente la espada celestial de las leyendas...?",
  str_homestory_N26dianying_90060301_65_dialog_content = "Jejeje... No está mal, ¿eh? ¡Tiene buen ojo para la calidad, señorita!",
  str_homestory_N26dianying_90060301_66_dialog_content = "Bastante impresionante, ¿eh? ¡Tiene buen ojo para la calidad, señorita!",
  str_homestory_N26dianying_90060301_67_dialog_content = "Esta no es la Espada Celestial.",
  str_homestory_N26dianying_90060301_68_dialog_content = "¿Eh? ¡¿C-Cómo lo supiste?!",
  str_homestory_N26dianying_90060301_69_dialog_content = "¿Eh? ¡¿C-Cómo lo supiste?!",
  str_homestory_N26dianying_90060301_70_dialog_content = "No puedo decir con seguridad cómo lo sé... Llámalo intuición, ¿supongo?",
  str_homestory_N26dianying_90060301_71_dialog_content = "Ejem... Bueno, ¡tienes razón! Esa espada no es la Espada Celestial en absoluto, porque la verdadera...",
  str_homestory_N26dianying_90060301_72_dialog_content = "¡Está la espada justo al lado!",
  str_homestory_N26dianying_90060301_73_dialog_content = "Ejem... Bueno, ¡tienes razón! Esa espada no es la Espada Celestial en absoluto, porque la verdadera...",
  str_homestory_N26dianying_90060301_74_dialog_content = "¡Está la espada justo al lado!",
  str_homestory_N26dianying_90060301_75_dialog_content = "¿En serio? ¡Déjeme ver! ... Uh, perdóname, ¡pero este tampoco es el verdadero negocio!",
  str_homestory_N26dianying_90060301_76_dialog_content = "(Maldita sea... ¡No hay forma de engañarla!)",
  str_homestory_N26dianying_90060301_77_dialog_content = "(Maldita sea... ¡No hay forma de engañarla!)",
  str_homestory_N26dianying_90060301_78_dialog_content = "Estoy seguro de que ya lo sabes, pero aquí en Village of Dragons, no tratamos de engañar a nuestra propia gente. Ahora, ¿podría decirme dónde puedo encontrar la Espada Celestial real?",
  str_homestory_N26dianying_90060301_79_dialog_content = "Bien, tú ganas... Aquí tienes.",
  str_homestory_N26dianying_90060301_80_dialog_content = "Bien, tú ganas... Aquí tienes.",
  str_homestory_N26dianying_90060301_81_dialog_content = "¿Una cinta de video?",
  str_homestory_N26dianying_90060301_82_dialog_content = "Ve a poner esta cinta en ese proyector de allí y presiona \"reproducir\".",
  str_homestory_N26dianying_90060301_83_dialog_content = "¡El proyector te mostrará las respuestas que buscas!",
  str_homestory_N26dianying_90060301_84_dialog_content = "Ve a poner esta cinta en ese proyector de allí y presiona \"reproducir\".",
  str_homestory_N26dianying_90060301_85_dialog_content = "¡El proyector te mostrará las respuestas que buscas!",
  str_homestory_N26dianying_90060301_86_dialog_content = "Hmm... Debería comenzar a reproducirse cuando presiono este botón, ¿verdad?",
  str_homestory_N26dianying_90060301_87_dialog_content = "... ¿Eh? ¿Por qué no se mueve la imagen de la cinta? Tampoco hay sonido...",
  str_homestory_N26dianying_90060301_88_dialog_content = "¡¡Espera, se está empezando a mover!!",
  str_homestory_N26dianying_90060301_89_dialog_content = "Bien, tú ganas... Aquí tienes.",
  str_homestory_N26dianying_90060301_90_dialog_content = "Bien, tú ganas... Aquí tienes.",
  str_homestory_N26dianying_90060301_91_dialog_content = "... ¡¿Un mapa?!",
  str_homestory_N26dianying_90060301_92_dialog_content = "Toma este mapa y síguelo hasta la ubicación marcada.",
  str_homestory_N26dianying_90060301_93_dialog_content = "¡El mapa te mostrará las respuestas que buscas!",
  str_homestory_N26dianying_90060301_94_dialog_content = "Toma este mapa y síguelo hasta la ubicación marcada.",
  str_homestory_N26dianying_90060301_95_dialog_content = "¡El mapa te mostrará las respuestas que buscas!",
  str_homestory_N26dianying_90060301_96_dialog_content = "Hmm... Estoy bastante seguro de que fui por el camino correcto, ¿no?",
  str_homestory_N26dianying_90060301_97_dialog_content = "Aún así, apenas puedo entender este mapa... La escritura en él también es apenas legible...",
  str_homestory_N26dianying_90060301_98_dialog_content = "Hmm... ¡Necesito echar un vistazo más de cerca a esto!",
  str_homestory_N26dianying_90060301_99_dialog_content = "Está bien, tú ganas... Mira hacia allá.",
  str_homestory_N26dianying_90060301_100_dialog_content = "Está bien, tú ganas... Mira hacia allá.",
  str_homestory_N26dianying_90060301_101_dialog_content = "¿Un buzón?",
  str_homestory_N26dianying_90060301_102_dialog_content = "Ve a leer lo que escribió el propietario anterior.",
  str_homestory_N26dianying_90060301_103_dialog_content = "¡El buzón te mostrará las respuestas que buscas!",
  str_homestory_N26dianying_90060301_104_dialog_content = "Ve a leer lo que escribió el propietario anterior.",
  str_homestory_N26dianying_90060301_105_dialog_content = "¡El buzón te mostrará las respuestas que buscas!",
  str_homestory_N26dianying_90060301_106_dialog_content = "Hmm... Este buzón es bastante alto, ¿eh?",
  str_homestory_N26dianying_90060301_107_dialog_content = "Pero incluso desde aquí abajo, puedo decir que la escritura es casi demasiado descuidada para leer...",
  str_homestory_N26dianying_90060301_108_dialog_content = "Hmm... ¡Necesito echar un vistazo más de cerca a esto!",
  str_homestory_N26dianying_90060301_108X1_dialog_content = "Bien, tú ganas... Aquí tienes. Dirígete hacia la dirección en la que estoy mirando.",
  str_homestory_N26dianying_90060301_108X2_dialog_content = "Bien, tú ganas... Aquí tienes. Dirígete hacia la dirección en la que estoy mirando.",
  str_homestory_N26dianying_90060301_108X3_dialog_content = "¿Adónde voy?",
  str_homestory_N26dianying_90060301_108X4_dialog_content = "No te preocupes por eso. ¡Solo sigue caminando hacia adelante!",
  str_homestory_N26dianying_90060301_108X5_dialog_content = "¡Siempre hay una nueva esperanza por delante en Village of Dragons, una tierra de gente excepcional!",
  str_homestory_N26dianying_90060301_108X6_dialog_content = "No te preocupes por eso. ¡Solo sigue caminando hacia adelante!",
  str_homestory_N26dianying_90060301_108X7_dialog_content = "¡Siempre hay una nueva esperanza por delante en Village of Dragons, una tierra de gente excepcional!",
  str_homestory_N26dianying_90060301_108X8_dialog_content = "¿¡R-En serio!? ¿No es demasiado informal...?",
  str_homestory_N26dianying_90060301_108X9_dialog_content = "Caray, tenía razón. He estado caminando durante tanto tiempo... ¡El jefe debe ser un embaucador!",
  str_homestory_N26dianying_90060301_108X10_dialog_content = "¿Eh? Puede ser esto...",
  str_homestory_N26dianying_90060301_109_dialog_content = "\"El camino del mundo es buscar el beneficio personal, y por esta razón, el mundo nunca cambiará. Para evitar que Heavenly Blade caiga en manos de los malvados...\"",
  str_homestory_N26dianying_90060301_110_dialog_content = "\"Un antiguo pozo en la Aldea de los Dragones fue bendecido con el poder de revelar la espada legendaria\".",
  str_homestory_N26dianying_90060301_111_dialog_content = "\"Imbuido de misteriosa Luminática, este pozo no mostrará el reflejo de ningún objeto que sostenga sus aguas\".",
  str_homestory_N26dianying_90060301_112_dialog_content = "\"Cuando la verdadera Espada Celestial se acerque, su imagen divina aparecerá dentro del pozo...\"",
  str_homestory_N26dianying_90060301_113_dialog_content = "\"El camino del mundo es buscar el beneficio personal, y por esta razón, el mundo nunca cambiará. Para evitar que Heavenly Blade caiga en manos de los malvados...\"",
  str_homestory_N26dianying_90060301_114_dialog_content = "\"Una tumbona en la Aldea de los dragones fue bendecida con el poder de revelar la espada legendaria\".",
  str_homestory_N26dianying_90060301_115_dialog_content = "\"Imbuida de misteriosa Luminatic, esta silla no permitirá que ninguna persona descanse sobre su asiento\".",
  str_homestory_N26dianying_90060301_116_dialog_content = "\"Cuando la verdadera Espada Celestial se acerque, su imagen divina aparecerá sobre el asiento...\"",
  str_homestory_N26dianying_90060301_117_dialog_content = "\"El camino del mundo es buscar el beneficio personal, y por esta razón, el mundo nunca cambiará. Para evitar que Heavenly Blade caiga en manos de los malvados...\"",
  str_homestory_N26dianying_90060301_118_dialog_content = "\"Un piano en Village of Dragons fue bendecido con el poder de revelar la espada legendaria\".",
  str_homestory_N26dianying_90060301_119_dialog_content = "\"Imbuido de la misteriosa Luminatic, este piano no permitirá que nadie lo toque\".",
  str_homestory_N26dianying_90060301_120_dialog_content = "\"Cuando la verdadera Espada Celestial se acerque, su imagen divina aparecerá sobre las teclas del piano...\"",
  str_homestory_N26dianying_90060301_121_dialog_content = "... ¿Yao? ¿Eres tú, Yao?",
  str_homestory_N26dianying_90060301_122_dialog_content = "Yao? ¿Eres realmente tú?",
  str_homestory_N26dianying_90060301_123_dialog_content = "¡Soy yo, la vecina de cuando éramos niños! ¡Hace años que no te veo, Yao!",
  str_homestory_N26dianying_90060301_124_dialog_content = "No desde el día que dejaste el pueblo para buscar trabajo... ¡Pensé que nunca te volvería a ver!",
  str_homestory_N26dianying_90060301_125_dialog_content = "De todos modos, ¿estás buscando algo, por casualidad?",
  str_homestory_N26dianying_90060301_126_dialog_content = "Después de que ambos dejamos el pueblo para buscar trabajo... ¡Pensé que nunca te volvería a ver!",
  str_homestory_N26dianying_90060301_127_dialog_content = "De todos modos, ¿estás buscando algo, por casualidad?",
  str_homestory_N26dianying_90060301_128_dialog_content = "Es una larga historia, pero... ¿Aún recuerdas dónde encontrar ese pozo? Conoces el uno, ¿verdad?",
  str_homestory_N26dianying_90060301_129_dialog_content = "Es una larga historia, pero... ¿Todavía recuerdas dónde encontrar esa tumbona? Conoces el uno, ¿verdad?",
  str_homestory_N26dianying_90060301_130_dialog_content = "Es una larga historia, pero... ¿Aún recuerdas dónde encontrar ese piano? Conoces el uno, ¿verdad?",
  str_homestory_N26dianying_90060301_131_dialog_content = "Claro, solo sígueme y te mostraré.",
  str_homestory_N26dianying_90060301_132_dialog_content = "¡Aquí estamos!",
  str_homestory_N26dianying_90060301_133_dialog_content = "Claro, solo sígueme y te mostraré.",
  str_homestory_N26dianying_90060301_134_dialog_content = "¡Muy bien, aquí estamos!",
  str_homestory_N26dianying_90060301_135_dialog_content = "Entonces... ¿De verdad viniste a casa solo para ver este pozo?",
  str_homestory_N26dianying_90060301_136_dialog_content = "Entonces... ¿De verdad viniste a casa solo para ver esta silla?",
  str_homestory_N26dianying_90060301_137_dialog_content = "Entonces... ¿De verdad viniste a casa solo para ver este piano?",
  str_homestory_N26dianying_90060301_138_dialog_content = "Bueno, la verdad es que... vine a buscar pistas sobre el paradero de Heavenly Blade.",
  str_homestory_N26dianying_90060301_139_dialog_content = "Mis señores me ordenaron que lo encontrara y se lo devolviera lo antes posible.",
  str_homestory_N26dianying_90060301_140_dialog_content = "<color=#FFB400>\"Señores\"</color>? ¿Como en \"más de uno\"?",
  str_homestory_N26dianying_90060301_141_dialog_content = "<color=#FFB400>\"Señores\"</color>? ¿Como en \"más de uno\"? ... ¡Oh, te refieres a tus jefes!",
  str_homestory_N26dianying_90060301_142_dialog_content = "Así es... Ambos me confiaron la misma búsqueda, en el mismo momento exacto, así que estoy aquí.",
  str_homestory_N26dianying_90060301_143_dialog_content = "Aunque no estoy seguro de lo que haré una vez que lo encuentre... ¿Cómo debo decidir a quién dárselo?",
  str_homestory_N26dianying_90060301_144_dialog_content = "¿Por qué no tener sus \"señores\" <color=#FFB400>luchar entre sí</color> ¿para ello?",
  str_homestory_N26dianying_90060301_145_dialog_content = "De todos modos, el agua de este pozo está totalmente turbia. No veo una \"imagen divina\" en ningún lado aquí...",
  str_homestory_N26dianying_90060301_146_dialog_content = "De todos modos, esta silla está totalmente vacía. No veo una \"imagen divina\" en ninguna parte...",
  str_homestory_N26dianying_90060301_147_dialog_content = "De todos modos, las teclas de este piano están impecables. No veo una \"imagen divina\" en ninguna parte de ellos...",
  str_homestory_N26dianying_90060301_147X1_dialog_content = "... ¿Yao? ¿Eres tú, Yao?",
  str_homestory_N26dianying_90060301_147X2_dialog_content = "Yao? ¿Eres realmente tú?",
  str_homestory_N26dianying_90060301_147X3_dialog_content = "¡Soy yo, la vecina de cuando éramos niños! ¡Hace años que no te veo, Yao!",
  str_homestory_N26dianying_90060301_147X4_dialog_content = "No desde el día que dejaste el pueblo para buscar trabajo... ¡Pensé que nunca te volvería a ver!",
  str_homestory_N26dianying_90060301_147X5_dialog_content = "De todos modos, ¿estás buscando algo, por casualidad?",
  str_homestory_N26dianying_90060301_147X6_dialog_content = "Después de que ambos dejamos el pueblo para buscar trabajo... ¡Pensé que nunca te volvería a ver!",
  str_homestory_N26dianying_90060301_147X7_dialog_content = "Por cierto, ¿qué estás haciendo?",
  str_homestory_N26dianying_90060301_147X8_dialog_content = "No lo menciones. Mis dos señores me pidieron que buscara la misma Heavenly Blade.",
  str_homestory_N26dianying_90060301_147X9_dialog_content = "Al final, no pude encontrar nada en absoluto...",
  str_homestory_N26dianying_90060301_147X10_dialog_content = "¡Así que has estado sirviendo a dos amos todo el tiempo! ¡Y después de que confié tanto en ti!",
  str_homestory_N26dianying_90060301_147X11_dialog_content = "¡¿L-Señor Zakura?! ¿Q-Qué haces aquí...?",
  str_homestory_N26dianying_90060301_147X12_dialog_content = "¡Debería estar haciéndote la misma pregunta! ¡Las palabras no pueden expresar lo decepcionado que estoy de ti, mi llamado \"siervo fiel\"!",
  str_homestory_N26dianying_90060301_147X13_dialog_content = "¡¿L-Lord Dragonscorch?! ¡¿También estás aquí?!",
  str_homestory_N26dianying_90060301_147X14_dialog_content = "Uh... ¿Q-Qué está pasando aquí?",
  str_homestory_N26dianying_90060301_147X15_dialog_content = "Uh... ¿Q-Qué está pasando aquí?",
  str_homestory_N26dianying_90060301_147X16_dialog_content = "Uh-oh... ¡Parece que se acabó la plantilla! ¡Cachero!",
  str_homestory_N26dianying_90060301_147X17_dialog_content = "Me preocupaba que esta tarea fuera demasiado grande para ti solo, así que arreglé que alguien te siguiera durante tu búsqueda...",
  str_homestory_N26dianying_90060301_147X18_dialog_content = "E infórmame todo a medida que suceda. Se suponía que serviría como una prueba de tus habilidades.",
  str_homestory_N26dianying_90060301_147X19_dialog_content = "Cuando supe que tu búsqueda había comenzado a dar frutos, corrí para ayudarte a encontrar la Espada Celestial...",
  str_homestory_N26dianying_90060301_147X20_dialog_content = "¡Solo para oírte pronunciar esas terribles, terribles palabras!",
  str_homestory_N26dianying_90060301_147X21_dialog_content = "¿Bien? ¡¿Qué tienes que decir en tu defensa, traidor?!",
  str_homestory_N26dianying_90060301_147X22_dialog_content = "Bueno... ya que las cosas han llegado a esto, ¡me haré responsable!",
  str_homestory_N26dianying_90060301_147X23_dialog_content = "¡Actúen, señores! Conozco las reglas. ¡Hoy es el día que muero!",
  str_homestory_N26dianying_90060301_147X24_dialog_content = "¿Ah?",
  str_homestory_N26dianying_90060301_147X25_dialog_content = "¿Matarte? ¿Qué clase de broma es esta?",
  str_homestory_N26dianying_90060301_147X26_dialog_content = "Como un guerrero orgulloso, nunca mataría a un oponente desarmado.",
  str_homestory_N26dianying_90060301_147X27_dialog_content = "A pesar de tu traición, tu remordimiento parece genuino... Muy bien, mi sirviente. Vámonos a casa, para que pueda ser castigado en consecuencia.",
  str_homestory_N26dianying_90060301_147X28_dialog_content = "¿Qué? Fui el primero en llegar, ¡así que el castigo de Dragonscorch debería ser lo primero!",
  str_homestory_N26dianying_90060301_147X29_dialog_content = "¡Digo Zakura!",
  str_homestory_N26dianying_90060301_147X30_dialog_content = "¡Digo Dragonscorch!",
  str_homestory_N26dianying_90060301_147X31_dialog_content = "¡Hoo-ah!",
  str_homestory_N26dianying_90060301_147X32_dialog_content = "Por favor, mis señores... Esto no es algo por lo que deban pelear...",
  str_homestory_N26dianying_90060301_148_dialog_content = "¡Así que has estado sirviendo a dos amos todo el tiempo! ¡Y después de que confié tanto en ti!",
  str_homestory_N26dianying_90060301_149_dialog_content = "¡¿L-Señor Zakura?! ¿Q-Qué haces aquí...?",
  str_homestory_N26dianying_90060301_150_dialog_content = "¡Debería estar haciéndote la misma pregunta! ¡Las palabras no pueden expresar lo decepcionado que estoy de ti, mi llamado \"siervo fiel\"!",
  str_homestory_N26dianying_90060301_151_dialog_content = "¡¿L-Lord Dragonscorch?! ¡¿También estás aquí?!",
  str_homestory_N26dianying_90060301_152_dialog_content = "Uh... ¿Q-Qué está pasando aquí?",
  str_homestory_N26dianying_90060301_153_dialog_content = "Uh... ¿Q-Qué está pasando aquí?",
  str_homestory_N26dianying_90060301_154_dialog_content = "Uh-oh... ¡Parece que se acabó la plantilla! ¡Cachero!",
  str_homestory_N26dianying_90060301_155_dialog_content = "Me preocupaba que esta tarea fuera demasiado grande para ti solo, así que arreglé que alguien te siguiera durante tu búsqueda...",
  str_homestory_N26dianying_90060301_156_dialog_content = "E infórmame todo a medida que suceda. Se suponía que serviría como una prueba de tus habilidades.",
  str_homestory_N26dianying_90060301_157_dialog_content = "Cuando supe que tu búsqueda había comenzado a dar frutos, corrí para ayudarte a encontrar la Espada Celestial...",
  str_homestory_N26dianying_90060301_158_dialog_content = "¡Solo para oírte pronunciar esas terribles, terribles palabras!",
  str_homestory_N26dianying_90060301_159_dialog_content = "¿Bien? ¡¿Qué tienes que decir en tu defensa, traidor?!",
  str_homestory_N26dianying_90060301_160_dialog_content = "¿Eh?",
  str_homestory_N26dianying_90060301_161_dialog_content = "¡¿Te atreves a burlarte de mí?!",
  str_homestory_N26dianying_90060301_162_dialog_content = "(Piensan exactamente igual, ¿no es así?)",
  str_homestory_N26dianying_90060301_163_dialog_content = "¡Están al unísono perfecto! ¡Cachero!",
  str_homestory_N26dianying_90060301_164_dialog_content = "Lord Dragonscorch... Este debe ser el destino. Qué mejor momento para decidir, de una vez por todas, quién es el más fuerte... ¡que ahora mismo!",
  str_homestory_N26dianying_90060301_165_dialog_content = "Me quitaste las palabras de la boca. ¡Hoy es el día en que Dragonscorch demuestra su supremacía!",
  str_homestory_N26dianying_90060301_166_dialog_content = "¡Hoo-ah!",
  str_homestory_N26dianying_90060301_167_dialog_content = "(Oh, mierda... ¡Están a punto de destrozarse! Tengo que hacer algo al respecto...)",
  str_homestory_N26dianying_90060301_168_option_content = "¡Encuentra la espada celestial!",
  str_homestory_N26dianying_90060301_169_dialog_content = "¡Oye! ¡No olvides el objetivo de tu misión!",
  str_homestory_N26dianying_90060301_170_dialog_content = "¡Así es! Lo que más importa ahora... ¡Es encontrar la Espada Celestial!",
  str_homestory_N26dianying_90060301_171_dialog_content = "Tal vez si miro más de cerca, aparecerá su \"imagen divina\"...",
  str_homestory_N26dianying_90060301_172_dialog_content = "¡¿E-Eh?!",
  str_homestory_N26dianying_90060301_173_dialog_content = "¡Mis señores! ¡Ven a ver, rápido!",
  str_homestory_N26dianying_90060301_174_dialog_content = "¿Mmm?",
  str_homestory_N26dianying_90060301_175_dialog_content = "¿Podría ser... La Espada Celestial?",
  str_homestory_N26dianying_90060301_176_dialog_content = "Qué es esto...?",
  str_homestory_N26dianying_90060301_177_dialog_content = "¿Por qué mi hoja brilla así?",
  str_homestory_N26dianying_90060301_178_dialog_content = "¡Pues ya era hora! ¡Por fin, Heavenly Blade se ha unido una vez más!",
  str_homestory_N26dianying_90060301_179_dialog_content = "¡Pues ya era hora! ¡Por fin, Heavenly Blade se ha unido una vez más!",
  str_homestory_N26dianying_90060301_180_dialog_content = "Te refieres a...",
  str_homestory_N26dianying_90060301_181_dialog_content = "¡Así es! La llamada \"Hoja Celestial\"... ¡En realidad es un par de espadas! Y solo cuando se reúnan, finalmente se revelará su verdadero poder.",
  str_homestory_N26dianying_90060301_182_dialog_content = "Hace mucho tiempo, tuve el privilegio de ver a dos grandes guerreros atravesar montones de eclipses con estas dos espadas...",
  str_homestory_N26dianying_90060301_183_dialog_content = "¡Así es! En realidad, hay DOS Heavenly Blades, ¡y su verdadero poder solo se revelará cuando se reúnan!",
  str_homestory_N26dianying_90060301_184_dialog_content = "Cuando aún era pequeño, vi a dos guerreros legendarios atravesar un ejército de Eclipsites con estas dos espadas...",
  str_homestory_N26dianying_90060301_185_dialog_content = "Esa fue la última vez que las dos espadas se usaron juntas. Después de esa batalla, cayeron en manos separadas y se mantuvieron alejados desde entonces.",
  str_homestory_N26dianying_90060301_186_dialog_content = "Esa fue la última vez que las dos espadas se usaron juntas. Después de esa batalla, cayeron en manos separadas y se mantuvieron alejados desde entonces.",
  str_homestory_N26dianying_90060301_187_dialog_content = "¡Pero ahora, Heavenly Blade está completa una vez más!",
  str_homestory_N26dianying_90060301_188_dialog_content = "¡Pero ahora, Heavenly Blade está completa una vez más!",
  str_homestory_N26dianying_90060301_189_dialog_content = "¡E-Así es, mis señores! A pesar de vuestras diferencias, vuestros objetivos son los mismos... ¡Incluso pensáis muy parecido!",
  str_homestory_N26dianying_90060301_190_dialog_content = "En lugar de pelear entre ustedes, ¿por qué no combinar sus fuerzas y salvar el mundo juntos?",
  str_homestory_N26dianying_90060301_191_dialog_content = "Mmm...",
  str_homestory_N26dianying_90060301_192_dialog_content = "Er...",
  str_homestory_N26dianying_90060301_193_dialog_content = "El sirviente tiene un punto válido... Después de todo, ambos buscamos el poder de Heavenly Blade.",
  str_homestory_N26dianying_90060301_194_dialog_content = "Y si combinamos nuestras fuerzas, aún seríamos los líderes de la facción más poderosa del mundo.",
  str_homestory_N26dianying_90060301_195_dialog_content = "En cuanto a ti, nuestro servidor \"fiel\"...",
  str_homestory_N26dianying_90060301_196_dialog_content = "UH oh...",
  str_homestory_N26dianying_90060301_197_dialog_content = "Has demostrado tu valía, ¡y Zakura siempre estará en deuda contigo!",
  str_homestory_N26dianying_90060301_198_dialog_content = "¡El Dragonscorch también debe mucho a tus diligentes esfuerzos!",
  str_homestory_N26dianying_90060301_199_dialog_content = "<size=45>¡Mis señores!</size>",
  str_homestory_N26dianying_90060301_200_dialog_content = "Jejeje... ¡Y así nació una nueva leyenda!",
  str_homestory_N26dianying_90060301_201_dialog_content = "¡Jejeje! ¡Y así nació una nueva leyenda!",
  str_homestory_N26dianying_90060301_202_dialog_content = "\"Al final, Zakura y Dragonscorch dejaron de lado sus diferencias y se fusionaron en un poderoso ejército\".",
  str_homestory_N26dianying_90060301_203_dialog_content = "\"Con su fuerza combinada, así como el poder de Heavenly Blade, el mundo fue bendecido con paz una vez más\".",
  str_homestory_N26dianying_90060301_204_dialog_content = "\"Al final, Zakura y Dragonscorch dejaron de lado sus diferencias y se fusionaron en un poderoso ejército\".",
  str_homestory_N26dianying_90060301_205_dialog_content = "\"Con su fuerza combinada, así como el poder de Heavenly Blade, el mundo fue bendecido con paz una vez más\".",
  str_homestory_N26dianying_90060301_206_option_content = "¡Intenta hacer las paces!",
  str_homestory_N26dianying_90060301_207_dialog_content = "¡Conoces a esos dos mejor que nadie! ¡Ve a arreglar las cosas entre ellos!",
  str_homestory_N26dianying_90060301_208_dialog_content = "¡Así es! ¡Como su sirviente, soy el único que puede resolver sus diferencias!",
  str_homestory_N26dianying_90060301_209_dialog_content = "Mis señores, ¿puedo hablar? A pesar de vuestras diferencias, vuestros objetivos son los mismos... ¡Incluso pensáis muy parecido!",
  str_homestory_N26dianying_90060301_210_dialog_content = "En lugar de pelear entre ustedes, ¿por qué no combinar sus fuerzas y salvar el mundo juntos?",
  str_homestory_N26dianying_90060301_211_dialog_content = "Mmm...",
  str_homestory_N26dianying_90060301_212_dialog_content = "Er...",
  str_homestory_N26dianying_90060301_213_dialog_content = "El sirviente hace un punto válido. Como líderes de nuestras respectivas facciones, es nuestro deber proteger al mundo de la amenaza de Eclipsite.",
  str_homestory_N26dianying_90060301_214_dialog_content = "Y si combinamos nuestras fuerzas, aún seríamos los líderes de la facción más poderosa del mundo.",
  str_homestory_N26dianying_90060301_215_dialog_content = "En cuanto a ti, nuestro servidor \"fiel\"...",
  str_homestory_N26dianying_90060301_216_dialog_content = "UH oh...",
  str_homestory_N26dianying_90060301_217_dialog_content = "Aunque fracasó en su búsqueda de Heavenly Blade... Puede haber otra forma de salvar el mundo.",
  str_homestory_N26dianying_90060301_218_dialog_content = "Si Dragonscorch y Zakura se convirtieran en uno, no habría necesidad de castigarte por tu traición.",
  str_homestory_N26dianying_90060301_219_dialog_content = "<size=45>¡Mis señores!</size>",
  str_homestory_N26dianying_90060301_220_dialog_content = "Jejeje... ¡Y así nació una nueva leyenda!",
  str_homestory_N26dianying_90060301_221_dialog_content = "¡Jejeje! ¡Y así nació una nueva leyenda!",
  str_homestory_N26dianying_90060301_222_dialog_content = "\"Al final, Zakura y Dragonscorch dejaron de lado sus diferencias y se fusionaron en un poderoso ejército\".",
  str_homestory_N26dianying_90060301_223_dialog_content = "\"Y así, el mundo fue bendecido con paz una vez más\".",
  str_homestory_N26dianying_90060301_224_dialog_content = "\"Al final, Zakura y Dragonscorch dejaron de lado sus diferencias y se fusionaron en un poderoso ejército\".",
  str_homestory_N26dianying_90060301_225_dialog_content = "\"Y así, el mundo fue bendecido con paz una vez más\".",
  str_homestory_N26dianying_90060301_226_option_content = "¡Sólo matame!",
  str_homestory_N26dianying_90060301_227_dialog_content = "¿Q-Qué debo hacer? Ya no veo la manera de hacer las cosas bien...",
  str_homestory_N26dianying_90060301_228_dialog_content = "No, espera... Es mi culpa que las cosas hayan salido así. Tengo que asumir la responsabilidad de mis acciones...",
  str_homestory_N26dianying_90060301_229_dialog_content = "¡Mis señores! ¡Yo soy el culpable de todo esto! ¡Si vas a matar a alguien, mátame a mí!",
  str_homestory_N26dianying_90060301_230_dialog_content = "¿Ah?",
  str_homestory_N26dianying_90060301_231_dialog_content = "¿Matarte? ¿Qué clase de broma es esta?",
  str_homestory_N26dianying_90060301_232_dialog_content = "Como un guerrero orgulloso, nunca mataría a un oponente desarmado.",
  str_homestory_N26dianying_90060301_233_dialog_content = "A pesar de tu traición, tu remordimiento parece genuino... Muy bien, mi sirviente. Vámonos a casa, para que pueda ser castigado en consecuencia.",
  str_homestory_N26dianying_90060301_234_dialog_content = "¿Qué? Fui el primero en llegar, ¡así que el castigo de Dragonscorch debería ser lo primero!",
  str_homestory_N26dianying_90060301_235_dialog_content = "¡Digo Zakura!",
  str_homestory_N26dianying_90060301_236_dialog_content = "¡Digo Dragonscorch!",
  str_homestory_N26dianying_90060301_237_dialog_content = "¡Hoo-ah!",
  str_homestory_N26dianying_90060301_238_dialog_content = "Por favor, mis señores... Esto no es algo por lo que deban pelear...",
  str_homestory_N26dianying_90060301_239_dialog_content = "Si no recuerdo mal, ¡esta tienda vende algunas de las mejores armas de todo Village of Dragons!",
  str_homestory_N26dianying_90060301_240_dialog_content = "¡¿Eh?!",
  str_homestory_N26dianying_90060301_241_dialog_content = "¿Qué pasó con todas las armas? ¡La tienda está completamente vacía!",
  str_homestory_N26dianying_90060301_242_dialog_content = "No me lo recuerdes... Lo siento amigo, pero estoy cerrando definitivamente.",
  str_homestory_N26dianying_90060301_243_dialog_content = "*Sollozando* No me lo recuerdes... Lo siento, pero la tienda está acabada.",
  str_homestory_N26dianying_90060301_244_dialog_content = "¿Qué paso?",
  str_homestory_N26dianying_90060301_245_dialog_content = "El pueblo fue saqueado por una banda de bandidos ayer mismo.",
  str_homestory_N26dianying_90060301_246_dialog_content = "El pueblo fue saqueado por una banda de bandidos ayer mismo.",
  str_homestory_N26dianying_90060301_247_dialog_content = "¡Se llevaron todo! Mis armas, mi dinero, la escritura de mi casa... ¡Incluso se llevaron mi armero mecánico favorito!",
  str_homestory_N26dianying_90060301_248_dialog_content = "¡Se llevaron todo! Mis proyectiles de agua bendita, mi dinero... ¡Incluso se llevaron mi estante de armas mecánicas favorito!",
  str_homestory_N26dianying_90060301_249_dialog_content = "¡No me queda nada!",
  str_homestory_N26dianying_90060301_250_dialog_content = "¡No me queda nada!",
  str_homestory_N26dianying_90060301_251_dialog_content = "N-Nada en absoluto?!",
  str_homestory_N26dianying_90060301_252_dialog_content = "Lo siento, sé que probablemente no sea el momento adecuado para preguntar... ¿Pero has oído hablar de la legendaria Heavenly Blade?",
  str_homestory_N26dianying_90060301_253_dialog_content = "¿Eh? Oh, déjame en paz ya...",
  str_homestory_N26dianying_90060301_254_dialog_content = "¿Eh? Oh, déjame en paz ya...",
  str_homestory_N26dianying_90060301_255_dialog_content = "¡¿No puedes ver que estoy revolcándome en la desesperación ahora mismo?!",
  str_homestory_N26dianying_90060301_256_dialog_content = "No puedo obligarme a sonreír en este momento, y mucho menos hablar de armas...",
  str_homestory_N26dianying_90060301_257_dialog_content = "Pero...",
  str_homestory_N26dianying_90060301_258_dialog_content = "Muy bien, eso es suficiente! ¡La tienda está cerrada, y eso es todo!",
  str_homestory_N26dianying_90060301_259_dialog_content = "Muy bien, eso es suficiente! ¡La tienda está cerrada, y eso es todo!",
  str_homestory_N26dianying_90060301_260_dialog_content = "¡Ahora mírate fuera y no vuelvas nunca más!",
  str_homestory_N26dianying_90060301_261_dialog_content = "Ahora, si me disculpan, tengo que ir a hacer unas nuevas conchas de agua bendita...",
  str_homestory_N26dianying_90060301_262_dialog_content = "¡N-No, por favor! ¡No te vayas...!",
  str_homestory_N26dianying_90060301_263_dialog_content = "... ¡¿Qué se supone que debo hacer ahora con Heavenly Blade?!"
}
return config
